import { useEffect, useMemo, useState } from 'react';
import { Activity, Bell, BrainCircuit, Braces, Box, Boxes, Cable, Check, ChevronDown, CircleAlert, Database, Gauge, GitBranch, Globe2, HardDrive, LayoutDashboard, LineChart, Link2, Menu, Network, Play, Plus, Radio, RefreshCw, Search, Server, Settings, ShieldCheck, Timer, Trash2, UserRound, Workflow, X } from 'lucide-react';
import { formatBytes, groupInventory, percent } from './inventory';
import './automation.css';
import './operations.css';
import type { AlertsResponse, AlertSeverity, AutomationSnapshot, BackupSnapshot, CiClass, CiCriticality, CmdbSnapshot, CollectorDashboardSnapshot, CollectorKind, ConfigurationItem, ConnectionStatus, DockerContainer, DockerInventory, HardwareInventory, HardwareOperations, Incident, IncidentLogCorrelation, Kind, LogRange, LogSearchResult, MetricPoint, MetricRange, MetricsSnapshot, Monitor, MonitorProtocol, MonitorsResponse, ProxmoxInventory, ProxmoxOperationsResponse, ProxmoxResource, Result, Run, SecurityEventType, SecuritySnapshot, ServiceNowChange, ServiceNowCmdbSnapshot, Session, TelemetryPoint, TelemetrySnapshot, Test, TopologyNode, TopologySnapshot } from './types';

const kindMeta: Record<Kind, { label: string; icon: typeof Globe2; className: string }> = {
  frontend: { label: 'Web Frontend', icon: Globe2, className: 'blue' }, api: { label: 'Backend API', icon: Braces, className: 'violet' },
  container: { label: 'Containers', icon: Box, className: 'amber' }, livenx: { label: 'LiveNX', icon: Network, className: 'green' }, livewire: { label: 'LiveWire', icon: Cable, className: 'cyan' }
};

export default function App() {
  const [tests, setTests] = useState<Test[]>([]); const [run, setRun] = useState<Run | null>(null); const [running, setRunning] = useState(false);
  const [filter, setFilter] = useState<'all' | Kind>('all'); const [query, setQuery] = useState(''); const [modal, setModal] = useState(false);
  const [view, setView] = useState<'overview' | 'services' | 'metrics' | 'performance' | 'logs' | 'cmdb' | 'security' | 'recovery' | 'sites' | 'alerts' | 'automation' | 'topology' | 'infrastructure' | 'operations' | 'docker' | 'hardware' | 'connections'>('overview');
  const [inventory, setInventory] = useState<ProxmoxInventory | null>(null); const [inventoryLoading, setInventoryLoading] = useState(true); const [inventoryError, setInventoryError] = useState('');
  const [proxmoxOperations,setProxmoxOperations]=useState<ProxmoxOperationsResponse|null>(null);const [proxmoxOperationsLoading,setProxmoxOperationsLoading]=useState(true);const [proxmoxOperationsError,setProxmoxOperationsError]=useState('');
  const [dockerInventory, setDockerInventory] = useState<DockerInventory | null>(null); const [dockerLoading, setDockerLoading] = useState(true); const [dockerError, setDockerError] = useState('');
  const [connections, setConnections] = useState<ConnectionStatus | null>(null);
  const [hardware,setHardware]=useState<HardwareInventory|null>(null);const [hardwareOperations,setHardwareOperations]=useState<HardwareOperations|null>(null);const [hardwareLoading,setHardwareLoading]=useState(true);const [hardwareError,setHardwareError]=useState('');
  const [monitors, setMonitors] = useState<MonitorsResponse | null>(null); const [monitorsLoading, setMonitorsLoading] = useState(true); const [monitorsError, setMonitorsError] = useState(''); const [monitorModal, setMonitorModal] = useState(false); const [runningMonitors, setRunningMonitors] = useState(false);
  const [alerts, setAlerts] = useState<AlertsResponse | null>(null); const [incidents, setIncidents] = useState<Incident[]>([]); const [alertsLoading, setAlertsLoading] = useState(true); const [alertsError, setAlertsError] = useState(''); const [alertModal, setAlertModal] = useState(false);
  const [automation,setAutomation]=useState<AutomationSnapshot|null>(null);const [automationLoading,setAutomationLoading]=useState(true);const [automationError,setAutomationError]=useState('');
  const [serviceNowCmdb,setServiceNowCmdb]=useState<ServiceNowCmdbSnapshot|null>(null);const [serviceNowLoading,setServiceNowLoading]=useState(true);const [serviceNowError,setServiceNowError]=useState('');
  const [topology,setTopology]=useState<TopologySnapshot|null>(null); const [topologyLoading,setTopologyLoading]=useState(true); const [topologyError,setTopologyError]=useState(''); const [mappingModal,setMappingModal]=useState(false);
  const [metrics,setMetrics]=useState<MetricsSnapshot|null>(null); const [metricsLoading,setMetricsLoading]=useState(true); const [metricsError,setMetricsError]=useState(''); const [metricRange,setMetricRange]=useState<MetricRange>('24h'); const [retentionModal,setRetentionModal]=useState(false);
  const [telemetry,setTelemetry]=useState<TelemetrySnapshot|null>(null); const [telemetryLoading,setTelemetryLoading]=useState(true); const [telemetryError,setTelemetryError]=useState(''); const [telemetryRange,setTelemetryRange]=useState<MetricRange>('24h');
  const [cmdb,setCmdb]=useState<CmdbSnapshot|null>(null); const [cmdbLoading,setCmdbLoading]=useState(true); const [cmdbError,setCmdbError]=useState(''); const [ciModal,setCiModal]=useState(false); const [editingCi,setEditingCi]=useState<ConfigurationItem|null>(null);
  const [logs,setLogs]=useState<LogSearchResult|null>(null);const [logsLoading,setLogsLoading]=useState(true);const [logsError,setLogsError]=useState('');
  const [session,setSession]=useState<Session|null>(null);
  const [security,setSecurity]=useState<SecuritySnapshot|null>(null);const [securityLoading,setSecurityLoading]=useState(false);const [securityError,setSecurityError]=useState('');
  const [backups,setBackups]=useState<BackupSnapshot|null>(null);const [backupsLoading,setBackupsLoading]=useState(false);const [backupsError,setBackupsError]=useState('');
  const [collectors,setCollectors]=useState<CollectorDashboardSnapshot|null>(null);const [collectorsLoading,setCollectorsLoading]=useState(false);const [collectorsError,setCollectorsError]=useState('');
  const [error, setError] = useState('');
  useEffect(() => { fetch('/api/session').then(async response => { if (!response.ok) throw new Error(await apiError(response)); return response.json(); }).then(setSession).catch(value => setError(value.message)); }, []);
  useEffect(() => { if(session?.permissions.administer) { void refreshSecurity(); void refreshBackups(); } }, [session?.user.subject,session?.permissions.administer]);
  useEffect(() => { fetch('/api/tests').then(async response => { if (!response.ok) throw new Error(await apiError(response)); return response.json(); }).then(setTests).catch(value => setError(value.message)); }, []);
  useEffect(() => { void refreshInventory(); void refreshProxmoxOperations(); void refreshDocker(); void refreshHardware(); void refreshConnections(); void refreshCollectors(); void refreshMonitors(); void refreshAlerts(); void refreshAutomation(); void refreshServiceNowCmdb(); void refreshTopology(); void refreshMetrics('24h'); void refreshTelemetry('24h'); void refreshCmdb(); void refreshLogs({range:'1h'}); }, []);
  const results = useMemo(() => new Map((run?.results || []).map(r => [r.id, r])), [run]);
  const visible = tests.filter(t => (filter === 'all' || t.kind === filter) && t.name.toLowerCase().includes(query.toLowerCase()));
  const passed = run?.gate.passed || 0; const failed = run ? run.gate.total - passed : 0;
  const score = run?.gate.score || 0;
  const medianLatency = run?.results.length ? median(run.results.map(result => result.latency)) : null;
  async function runSuite() { setRunning(true); setRun(null); setError(''); try { const response = await fetch('/api/runs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ simulate: true }) }); if (!response.ok) throw new Error(await apiError(response)); setRun(await response.json()); } catch (value) { setError(value instanceof Error ? value.message : 'Unable to run suite'); } finally { setRunning(false); } }
  async function addTest(data: Omit<Test, 'id'>) { setError(''); try { const response = await fetch('/api/tests', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) }); if (!response.ok) throw new Error(await apiError(response)); const created = await response.json(); setTests(value => [...value, created]); setModal(false); } catch (value) { setError(value instanceof Error ? value.message : 'Unable to add test'); } }
  async function refreshInventory() { setInventoryLoading(true); setInventoryError(''); try { const response = await fetch('/api/inventory'); if (!response.ok) throw new Error(`Inventory request failed with HTTP ${response.status}`); setInventory(await response.json()); } catch (error) { setInventoryError(error instanceof Error ? error.message : 'Unable to load Proxmox inventory'); } finally { setInventoryLoading(false); } }
  async function refreshProxmoxOperations(){setProxmoxOperationsLoading(true);setProxmoxOperationsError('');try{const response=await fetch('/api/proxmox/operations');if(!response.ok)throw new Error(await apiError(response));setProxmoxOperations(await response.json())}catch(value){setProxmoxOperationsError(value instanceof Error?value.message:'Unable to load Proxmox operations')}finally{setProxmoxOperationsLoading(false)}}
  async function collectProxmoxOperations(){setProxmoxOperationsLoading(true);setProxmoxOperationsError('');try{const response=await fetch('/api/proxmox/operations/collect',{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshProxmoxOperations()}catch(value){setProxmoxOperationsError(value instanceof Error?value.message:'Unable to collect Proxmox operations');setProxmoxOperationsLoading(false)}}
  async function refreshDocker() { setDockerLoading(true); setDockerError(''); try { const response = await fetch('/api/docker/inventory'); if (!response.ok) throw new Error(`Docker request failed with HTTP ${response.status}`); setDockerInventory(await response.json()); } catch (error) { setDockerError(error instanceof Error ? error.message : 'Unable to load Docker inventory'); } finally { setDockerLoading(false); } }
  async function refreshConnections() { try { const response = await fetch('/api/connections'); if (response.ok) setConnections(await response.json()); } catch { setConnections(null); } }
  async function refreshHardware(){setHardwareLoading(true);setHardwareError('');try{const [inventoryResponse,operationsResponse]=await Promise.all([fetch('/api/hardware/inventory'),fetch('/api/hardware/operations')]);if(!inventoryResponse.ok)throw new Error(await apiError(inventoryResponse));if(!operationsResponse.ok)throw new Error(await apiError(operationsResponse));setHardware(await inventoryResponse.json());setHardwareOperations(await operationsResponse.json())}catch(value){setHardwareError(value instanceof Error?value.message:'Unable to discover hardware')}finally{setHardwareLoading(false)}}
  async function scheduleHardwareMaintenance(deviceId:string){const startsAt=new Date();const endsAt=new Date(startsAt.getTime()+2*60*60*1000);const response=await fetch('/api/hardware/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deviceId,reason:'Planned maintenance',startsAt:startsAt.toISOString(),endsAt:endsAt.toISOString()})});if(!response.ok)throw new Error(await apiError(response));await refreshHardware()}
  async function baselineHardware(deviceId:string){const response=await fetch(`/api/hardware/baselines/${encodeURIComponent(deviceId)}`,{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshHardware()}
  async function refreshMonitors() { setMonitorsLoading(true); setMonitorsError(''); try { const response = await fetch('/api/monitors'); if (!response.ok) throw new Error(`Monitor request failed with HTTP ${response.status}`); setMonitors(await response.json()); } catch (error) { setMonitorsError(error instanceof Error ? error.message : 'Unable to load service monitors'); } finally { setMonitorsLoading(false); } }
  async function runAllMonitors() { setRunningMonitors(true); try { const response = await fetch('/api/monitors/run-all', { method: 'POST' }); if (!response.ok) throw new Error(`Run failed with HTTP ${response.status}`); await refreshMonitors(); } catch (error) { setMonitorsError(error instanceof Error ? error.message : 'Unable to run monitors'); } finally { setRunningMonitors(false); } }
  async function runMonitor(id:string) { const response = await fetch(`/api/monitors/${encodeURIComponent(id)}/run`, { method:'POST' }); if (!response.ok) throw new Error(`Run failed with HTTP ${response.status}`); await refreshMonitors(); }
  async function addMonitor(input:{name:string;protocol:MonitorProtocol;target:string;intervalSeconds:number;timeoutMs:number;expectedStatus?:number}) { const response = await fetch('/api/monitors', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(input) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || 'Unable to add monitor'); setMonitorModal(false); await refreshMonitors(); }
  async function refreshAlerts() { setAlertsLoading(true); setAlertsError(''); try { const [rulesResponse, incidentsResponse] = await Promise.all([fetch('/api/alerts'),fetch('/api/incidents')]); if (!rulesResponse.ok) throw new Error(await apiError(rulesResponse)); if (!incidentsResponse.ok) throw new Error(await apiError(incidentsResponse)); setAlerts(await rulesResponse.json()); setIncidents(await incidentsResponse.json()); } catch (value) { setAlertsError(value instanceof Error ? value.message : 'Unable to load alerts'); } finally { setAlertsLoading(false); } }
  async function addAlert(input:{name:string;monitorId:string;failureThreshold:number;cooldownSeconds:number;severity:AlertSeverity}) { const response = await fetch('/api/alerts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)}); if (!response.ok) throw new Error(await apiError(response)); setAlertModal(false); await refreshAlerts(); }
  async function acknowledgeIncident(id:string) { const response = await fetch(`/api/incidents/${encodeURIComponent(id)}/acknowledge`,{method:'POST'}); if (!response.ok) throw new Error(await apiError(response)); await refreshAlerts(); }
  async function suppressAlert(id:string) { const response = await fetch(`/api/alerts/${encodeURIComponent(id)}/suppress`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({minutes:60})}); if (!response.ok) throw new Error(await apiError(response)); await refreshAlerts(); }
  async function refreshAutomation(){setAutomationLoading(true);setAutomationError('');try{const response=await fetch('/api/automation');if(!response.ok)throw new Error(await apiError(response));setAutomation(await response.json())}catch(value){setAutomationError(value instanceof Error?value.message:'Unable to load automation history')}finally{setAutomationLoading(false)}}
  async function retryDelivery(id:string){const response=await fetch(`/api/notifications/${encodeURIComponent(id)}/retry`,{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await Promise.all([refreshAutomation(),refreshAlerts()])}
  async function refreshServiceNowCmdb(){setServiceNowLoading(true);setServiceNowError('');try{const response=await fetch('/api/integrations/servicenow/cmdb');if(!response.ok)throw new Error(await apiError(response));setServiceNowCmdb(await response.json())}catch(value){setServiceNowError(value instanceof Error?value.message:'Unable to load ServiceNow CMDB status')}finally{setServiceNowLoading(false)}}
  async function syncServiceNowCmdb(){const response=await fetch('/api/integrations/servicenow/cmdb/sync',{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshServiceNowCmdb()}
  async function createServiceNowChange(input:{ciId:string;shortDescription:string;description:string;startsAt:string;endsAt:string;riskAnalysis:string}){const response=await fetch('/api/integrations/servicenow/changes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok)throw new Error(await apiError(response));const created=await response.json() as ServiceNowChange;await refreshServiceNowCmdb();return created}
  async function refreshTopology() { setTopologyLoading(true); setTopologyError(''); try { const response=await fetch('/api/topology'); if(!response.ok)throw new Error(await apiError(response)); setTopology(await response.json()); } catch(value) { setTopologyError(value instanceof Error?value.message:'Unable to build topology'); } finally { setTopologyLoading(false); } }
  async function addMapping(input:{monitorId:string;resourceId:string}) { const response=await fetch('/api/topology/mappings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)}); if(!response.ok)throw new Error(await apiError(response)); setMappingModal(false); await refreshTopology(); }
  async function removeMapping(id:string) { const response=await fetch(`/api/topology/mappings/${encodeURIComponent(id)}`,{method:'DELETE'}); if(!response.ok)throw new Error(await apiError(response)); await refreshTopology(); }
  async function refreshMetrics(range:MetricRange=metricRange) { setMetricsLoading(true);setMetricsError('');try{const response=await fetch(`/api/metrics?range=${range}`);if(!response.ok)throw new Error(await apiError(response));setMetricRange(range);setMetrics(await response.json())}catch(value){setMetricsError(value instanceof Error?value.message:'Unable to load metrics')}finally{setMetricsLoading(false)} }
  async function updateRetention(input:{days:number;maxResults:number}) { const response=await fetch('/api/metrics/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok)throw new Error(await apiError(response));setRetentionModal(false);await refreshMetrics(); }
  async function refreshTelemetry(range:MetricRange=telemetryRange) { setTelemetryLoading(true);setTelemetryError('');try{const response=await fetch(`/api/infrastructure/metrics?range=${range}`);if(!response.ok)throw new Error(await apiError(response));setTelemetryRange(range);setTelemetry(await response.json())}catch(value){setTelemetryError(value instanceof Error?value.message:'Unable to load infrastructure telemetry')}finally{setTelemetryLoading(false)} }
  async function collectTelemetry(){const response=await fetch('/api/infrastructure/metrics/collect',{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshTelemetry()}
  async function refreshCmdb(){setCmdbLoading(true);setCmdbError('');try{const response=await fetch('/api/cmdb/snapshot');if(!response.ok)throw new Error(await apiError(response));setCmdb(await response.json())}catch(value){setCmdbError(value instanceof Error?value.message:'Unable to load configuration items')}finally{setCmdbLoading(false)}}
  async function reconcileCmdb(){const response=await fetch('/api/cmdb/reconcile',{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshCmdb()}
  async function saveCi(input:Record<string,unknown>,id?:string){const response=await fetch(id?`/api/cmdb/items/${encodeURIComponent(id)}`:'/api/cmdb/items',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok)throw new Error(await apiError(response));setCiModal(false);setEditingCi(null);await refreshCmdb()}
  async function refreshLogs(filters:{range?:LogRange;level?:string;source?:string;search?:string}={}){setLogsLoading(true);setLogsError('');try{const params=new URLSearchParams();params.set('range',filters.range||logs?.range||'1h');if(filters.level&&filters.level!=='all')params.set('level',filters.level);if(filters.source&&filters.source!=='all')params.set('source',filters.source);if(filters.search)params.set('search',filters.search);const response=await fetch(`/api/logs?${params}`);if(!response.ok)throw new Error(await apiError(response));setLogs(await response.json())}catch(value){setLogsError(value instanceof Error?value.message:'Unable to query logs')}finally{setLogsLoading(false)}}
  async function refreshSecurity(type?:SecurityEventType){setSecurityLoading(true);setSecurityError('');try{const response=await fetch(`/api/security/events${type?`?type=${type}`:''}`);if(!response.ok)throw new Error(await apiError(response));setSecurity(await response.json())}catch(value){setSecurityError(value instanceof Error?value.message:'Unable to load security events')}finally{setSecurityLoading(false)}}
  async function refreshBackups(){setBackupsLoading(true);setBackupsError('');try{const response=await fetch('/api/backups');if(!response.ok)throw new Error(await apiError(response));setBackups(await response.json())}catch(value){setBackupsError(value instanceof Error?value.message:'Unable to load backups')}finally{setBackupsLoading(false)}}
  async function createBackup(){setBackupsLoading(true);setBackupsError('');try{const response=await fetch('/api/backups',{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshBackups()}catch(value){setBackupsError(value instanceof Error?value.message:'Unable to create backup');setBackupsLoading(false)}}
  async function verifyBackup(id:string){setBackupsLoading(true);setBackupsError('');try{const response=await fetch(`/api/backups/${encodeURIComponent(id)}/verify`,{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshBackups()}catch(value){setBackupsError(value instanceof Error?value.message:'Backup verification failed');setBackupsLoading(false)}}
  async function replicateBackup(id:string){setBackupsLoading(true);setBackupsError('');try{const response=await fetch(`/api/backups/${encodeURIComponent(id)}/replicate`,{method:'POST'});if(!response.ok)throw new Error(await apiError(response));await refreshBackups()}catch(value){setBackupsError(value instanceof Error?value.message:'Backup replication failed');setBackupsLoading(false)}}
  async function refreshCollectors(){setCollectorsLoading(true);setCollectorsError('');try{const response=await fetch('/api/collectors');if(!response.ok)throw new Error(await apiError(response));setCollectors(await response.json())}catch(value){setCollectorsError(value instanceof Error?value.message:'Unable to load remote collectors')}finally{setCollectorsLoading(false)}}
  async function enrollCollector(input:{name:string;site:string;kind:CollectorKind;intervalSeconds:number}){const response=await fetch('/api/collectors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok)throw new Error(await apiError(response));const result=await response.json();await refreshCollectors();return result.token as string;}
  async function rotateCollector(id:string){const response=await fetch(`/api/collectors/${encodeURIComponent(id)}/rotate`,{method:'POST'});if(!response.ok)throw new Error(await apiError(response));const result=await response.json();await refreshCollectors();return result.token as string;}
  async function removeCollector(id:string){const response=await fetch(`/api/collectors/${encodeURIComponent(id)}`,{method:'DELETE'});if(!response.ok)throw new Error(await apiError(response));await refreshCollectors();}
  const viewTitle = ({ overview: 'Durability overview', services: 'Service monitoring', metrics:'Historical metrics', performance:'Infrastructure performance', logs:'Centralized logs', cmdb:'Configuration management', security:'Security audit', recovery:'Backup and recovery', sites:'Sites and collectors', alerts: 'Alerts and incidents', automation:'Integrations and automation', topology: 'Dependency topology', infrastructure: 'Proxmox infrastructure', operations:'Proxmox operations', docker: 'Docker applications', hardware:'Physical infrastructure', connections: 'Connections' } as const)[view];

  return <div className="shell">
    <aside className="sidebar">
      <div className="brand"><span className="brand-mark"><Activity size={19}/></span><span>Sentinel<span className="brand-accent">Lab</span></span></div>
      <nav><Nav active={view === 'overview'} icon={LayoutDashboard} label="Overview" onClick={() => setView('overview')}/><Nav active={view === 'services'} icon={Activity} label="Services" count={monitors?.monitors.length} onClick={() => setView('services')}/><Nav active={view==='metrics'} icon={LineChart} label="Service metrics" onClick={()=>setView('metrics')}/><Nav active={view==='performance'} icon={Gauge} label="Performance" onClick={()=>setView('performance')}/><Nav active={view==='logs'} icon={Braces} label="Logs" count={logs?.summary.errors} onClick={()=>setView('logs')}/><Nav active={view==='cmdb'} icon={Database} label="CMDB" count={cmdb?.items.length} onClick={()=>setView('cmdb')}/>{session?.permissions.administer&&<><Nav active={view==='security'} icon={ShieldCheck} label="Security" count={(security?.summary.failures||0)+(security?.summary.denied||0)} onClick={()=>setView('security')}/><Nav active={view==='recovery'} icon={HardDrive} label="Recovery" count={backups?.summary.count} onClick={()=>setView('recovery')}/></>}<Nav active={view === 'alerts'} icon={Bell} label="Alerts" count={incidents.filter(item=>item.status!=='resolved').length} onClick={() => setView('alerts')}/><Nav active={view==='topology'} icon={GitBranch} label="Topology" count={topology?.correlations.length} onClick={()=>setView('topology')}/><Nav icon={Radio} label="Test suites" count={tests.length}/></nav>
      <div className="nav-section">INTEGRATIONS</div>
      <nav><Nav active={view==='automation'} icon={Workflow} label="Automation" count={automation?.summary.failed} onClick={()=>setView('automation')}/><Nav active={view==='sites'} icon={Globe2} label="Sites" count={collectors?.summary.collectors} onClick={()=>setView('sites')}/><Nav active={view === 'infrastructure'} icon={Server} label="Proxmox" dot onClick={() => setView('infrastructure')}/><Nav active={view==='operations'} icon={ShieldCheck} label="Cluster health" count={(proxmoxOperations?.current?.summary.critical||0)+(proxmoxOperations?.current?.summary.warnings||0)} onClick={()=>setView('operations')}/><Nav active={view === 'hardware'} icon={HardDrive} label="Hardware" count={hardware?.summary.devices} onClick={() => setView('hardware')}/><Nav icon={Network} label="LiveNX" dot/><Nav icon={Cable} label="LiveWire" dot/><Nav active={view === 'docker'} icon={Box} label="Docker" dot onClick={() => setView('docker')}/></nav>
      <div className="side-bottom"><div className="lab-health"><div><span className="pulse"/> LAB HEALTH</div><strong>All systems operational</strong></div><Nav active={view === 'connections'} icon={Settings} label="Connections" onClick={() => setView('connections')}/></div>
    </aside>
    <main>
      <header><button className="mobile-menu"><Menu/></button><div><span className="crumb">Reliability workspace</span><h1>{viewTitle}</h1></div><div className="header-actions">{session&&<div className="session-user" title={session.user.email||session.user.subject}><UserRound size={15}/><span><strong>{session.user.name}</strong><small>{session.user.role}</small></span></div>}{view === 'overview' ? <><div className="environment"><span/> Staging <ChevronDown size={14}/></div>{session?.permissions.administer&&<button className="secondary" onClick={() => setModal(true)}><Plus size={17}/> Add test</button>}{session?.permissions.operate&&<button className="primary" onClick={runSuite} disabled={running}><Play size={16} fill="currentColor"/>{running ? 'Running suite…' : 'Run full suite'}</button>}</> : view === 'services' ? <>{session?.permissions.administer&&<button className="secondary" onClick={() => setMonitorModal(true)}><Plus size={16}/>Add monitor</button>}{session?.permissions.operate&&<button className="primary" onClick={runAllMonitors} disabled={runningMonitors}><Play size={15}/>{runningMonitors ? 'Running…' : 'Run all'}</button>}</> : view==='metrics'?<>{session?.permissions.administer&&<button className="secondary" onClick={()=>setRetentionModal(true)}><Database size={16}/>Retention</button>}<button className="primary" onClick={()=>refreshMetrics()}><RefreshCw size={16}/>Refresh</button></> : view==='performance'?<><button className="secondary" onClick={()=>refreshTelemetry()}><RefreshCw size={16}/>Refresh</button>{session?.permissions.operate&&<button className="primary" onClick={collectTelemetry}><Activity size={16}/>Collect now</button>}</> : view==='logs'?<button className="primary" onClick={()=>refreshLogs()}><RefreshCw size={16}/>Refresh logs</button> : view==='cmdb'?<>{session?.permissions.operate&&<button className="secondary" onClick={reconcileCmdb}><RefreshCw size={16}/>Reconcile</button>}{session?.permissions.administer&&<button className="primary" onClick={()=>setCiModal(true)}><Plus size={16}/>Add CI</button>}</> : view==='security'?<button className="primary" onClick={()=>refreshSecurity()}><RefreshCw size={16}/>Refresh audit</button> : view==='recovery'?<><button className="secondary" onClick={refreshBackups}><RefreshCw size={16}/>Refresh</button><button className="primary" onClick={createBackup} disabled={backupsLoading}><HardDrive size={16}/>{backupsLoading?'Working…':'Back up now'}</button></> : view==='sites'?<button className="primary" onClick={refreshCollectors}><RefreshCw size={16}/>Refresh sites</button> : view === 'alerts' ? <><button className="secondary" onClick={refreshAlerts}><RefreshCw size={16}/>Refresh</button>{session?.permissions.administer&&<button className="primary" onClick={()=>setAlertModal(true)}><Plus size={16}/>Add rule</button>}</> : view === 'automation' ? <button className="primary" onClick={()=>Promise.all([refreshAutomation(),refreshServiceNowCmdb()])}><RefreshCw size={16}/>Refresh automation</button> : view === 'topology' ? <><button className="secondary" onClick={refreshTopology}><RefreshCw size={16}/>Refresh</button>{session?.permissions.operate&&<button className="primary" onClick={()=>setMappingModal(true)}><Link2 size={16}/>Map service</button>}</> : view==='operations'?<button className="primary" onClick={collectProxmoxOperations} disabled={proxmoxOperationsLoading}><RefreshCw className={proxmoxOperationsLoading?'spin':''} size={16}/>{proxmoxOperationsLoading?'Collecting…':'Collect now'}</button> : view === 'infrastructure' ? <button className="secondary" onClick={refreshInventory} disabled={inventoryLoading}><RefreshCw size={16}/>{inventoryLoading ? 'Refreshing…' : 'Refresh inventory'}</button> : view === 'docker' ? <button className="secondary" onClick={refreshDocker} disabled={dockerLoading}><RefreshCw size={16}/>{dockerLoading ? 'Refreshing…' : 'Refresh containers'}</button> : <button className="secondary" onClick={refreshConnections}><RefreshCw size={16}/>Refresh status</button>}</div></header>
      {view === 'overview' ? <section className="content">
        {error && <div className="error-banner" role="alert"><CircleAlert size={17}/><span>{error}</span><button onClick={() => setError('')} aria-label="Dismiss error"><X size={15}/></button></div>}
        <div className="notice"><span className="notice-icon"><ShieldCheck size={19}/></span><div><strong>Release readiness workspace</strong><p>Continuously validate user journeys, API contracts, container health, and LiveNX ↔ LiveWire telemetry before every release.</p></div><button>Configure gates <ChevronDown size={15}/></button></div>
        <div className="metric-grid">
          <Metric label="Durability score" value={run ? `${score}%` : '—'} detail={run ? `${passed} of ${run.results.length} checks passed` : 'Run the suite to calculate'} icon={Gauge} tone={run ? (score > 89 ? 'good' : 'bad') : undefined} gauge={run ? score : undefined}/>
          <Metric label="Active checks" value={String(tests.length)} detail="Across 5 test surfaces" icon={Activity}/>
          <Metric label="Median response" value={medianLatency === null ? '—' : `${medianLatency}ms`} detail="Target threshold < 500ms" icon={Timer}/>
          <Metric label="Regressions" value={run ? String(failed) : '—'} detail={run ? failed ? `${run.gate.criticalFailures} release blocking` : 'No regressions found' : 'No run results yet'} icon={CircleAlert} tone={failed ? 'bad' : undefined}/>
        </div>
        <div className="main-grid">
          <section className="panel suite-panel"><div className="panel-head"><div><h2>Test surface</h2><p>Coverage and current state across the stack</p></div><div className="search"><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search checks"/></div></div>
            <div className="tabs"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>All <span>{tests.length}</span></button>{(Object.keys(kindMeta) as Kind[]).map(k=><button key={k} className={filter===k?'active':''} onClick={()=>setFilter(k)}>{kindMeta[k].label}</button>)}</div>
            <div className="test-list">{visible.map(test => <TestRow key={test.id} test={test} result={results.get(test.id)} running={running}/>)}</div>
          </section>
          <aside className="right-col">
            <section className="panel release"><div className="panel-head"><div><h2>Release gate</h2><p>{run ? `Run ${run.id.slice(0, 12)}` : 'Awaiting first run'}</p></div><span className={`gate ${run?.gate.status || 'blocked'}`}>{run?.gate.status.toUpperCase() || 'PENDING'}</span></div>
              <div className="ring" style={{'--score': `${score * 3.6}deg`} as React.CSSProperties}><div><strong>{score}</strong><span>/ 100</span></div></div>
              <div className="gate-row"><span><Check size={14}/> Required checks</span><strong>{run ? `${passed}/${run.results.length}` : '—'}</strong></div><div className="gate-row"><span><CircleAlert size={14}/> Blocking issues</span><strong className="red">{run ? run.gate.criticalFailures : '—'}</strong></div>
              <button className="wide">View gate details</button>
            </section>
            <section className="panel signals"><div className="panel-head"><div><h2>Live telemetry</h2><p>Integration signals</p></div><span className="live"><i/>LIVE</span></div>
              <Signal icon={Network} title="LiveNX telemetry" detail="Last flow 12s ago" value="Healthy"/><Signal icon={Cable} title="LiveWire export" detail="42.8k flows/sec" value="Active"/><Signal icon={Box} title="Container fleet" detail="12 of 12 healthy" value="Stable"/>
              <div className="spark"><span style={{height:'34%'}}/><span style={{height:'46%'}}/><span style={{height:'40%'}}/><span style={{height:'68%'}}/><span style={{height:'58%'}}/><span style={{height:'82%'}}/><span style={{height:'72%'}}/><span style={{height:'88%'}}/><span style={{height:'65%'}}/><span style={{height:'76%'}}/><span style={{height:'84%'}}/><span style={{height:'92%'}}/></div>
            </section>
          </aside>
        </div>
      </section> : view === 'services' ? <ServicesDashboard data={monitors} loading={monitorsLoading} error={monitorsError} refresh={refreshMonitors} runMonitor={runMonitor}/> : view==='metrics'?<MetricsDashboard data={metrics} loading={metricsLoading} error={metricsError} range={metricRange} selectRange={refreshMetrics}/>: view==='performance'?<PerformanceDashboard data={telemetry} loading={telemetryLoading} error={telemetryError} range={telemetryRange} selectRange={refreshTelemetry}/>:view==='logs'?<LogsDashboard data={logs} loading={logsLoading} error={logsError} incidents={incidents.filter(item=>item.status!=='resolved')} search={refreshLogs}/>:view==='cmdb'?<CmdbDashboard data={cmdb} loading={cmdbLoading} error={cmdbError} refresh={refreshCmdb} edit={setEditingCi}/>:view==='security'?<SecurityDashboard data={security} loading={securityLoading} error={securityError} refresh={refreshSecurity}/>:view==='recovery'?<RecoveryDashboard data={backups} loading={backupsLoading} error={backupsError} refresh={refreshBackups} verify={verifyBackup} replicate={replicateBackup}/>:view==='sites'?<CollectorsDashboard data={collectors} loading={collectorsLoading} error={collectorsError} admin={Boolean(session?.permissions.administer)} refresh={refreshCollectors} enroll={enrollCollector} rotate={rotateCollector} remove={removeCollector}/>: view === 'alerts' ? <AlertsDashboard data={alerts} incidents={incidents} monitors={monitors?.monitors || []} loading={alertsLoading} error={alertsError} acknowledge={acknowledgeIncident} suppress={suppressAlert}/> : view === 'automation' ? <AutomationDashboard data={automation} serviceNow={serviceNowCmdb} cis={cmdb?.items||[]} incidents={incidents} loading={automationLoading||serviceNowLoading} error={automationError||serviceNowError} operate={Boolean(session?.permissions.operate)} refresh={async()=>{await Promise.all([refreshAutomation(),refreshServiceNowCmdb()])}} retry={retryDelivery} syncCmdb={syncServiceNowCmdb} createChange={createServiceNowChange}/> : view === 'topology' ? <TopologyDashboard data={topology} loading={topologyLoading} error={topologyError} refresh={refreshTopology} removeMapping={removeMapping}/> : view==='operations'?<ProxmoxOperationsDashboard data={proxmoxOperations} loading={proxmoxOperationsLoading} error={proxmoxOperationsError} refresh={refreshProxmoxOperations}/> : view === 'infrastructure' ? <InventoryDashboard inventory={inventory} loading={inventoryLoading} error={inventoryError} refresh={refreshInventory}/> : view === 'docker' ? <DockerDashboard inventory={dockerInventory} loading={dockerLoading} error={dockerError} refresh={refreshDocker}/> : view==='hardware'?<HardwareDashboard inventory={hardware} operations={hardwareOperations} loading={hardwareLoading} error={hardwareError} refresh={refreshHardware} maintain={scheduleHardwareMaintenance} baseline={baselineHardware}/>:<ConnectionsDashboard status={connections}/>}
    </main>{modal && <AddModal close={()=>setModal(false)} save={addTest}/>}{monitorModal && <AddMonitorModal close={() => setMonitorModal(false)} save={addMonitor}/>}{alertModal && <AddAlertModal close={()=>setAlertModal(false)} save={addAlert} monitors={monitors?.monitors || []}/>}{mappingModal&&topology&&<AddMappingModal close={()=>setMappingModal(false)} save={addMapping} monitors={monitors?.monitors||[]} nodes={topology.nodes}/>}{retentionModal&&metrics&&<RetentionModal close={()=>setRetentionModal(false)} save={updateRetention} current={metrics.retention}/>} {(ciModal||editingCi)&&<CiModal item={editingCi} close={()=>{setCiModal(false);setEditingCi(null)}} save={saveCi}/>}
  </div>;
}

function Nav({icon:Icon,label,active,count,dot,onClick}:{icon:typeof Activity,label:string,active?:boolean,count?:number,dot?:boolean,onClick?:()=>void}) { return <button className={`nav-item ${active?'active':''}`} onClick={onClick}><Icon size={18}/><span>{label}</span>{count!==undefined&&<em>{count}</em>}{dot&&<i/>}</button> }
function Metric({label,value,detail,icon:Icon,tone,gauge}:{label:string,value:string,detail:string,icon:typeof Activity,tone?:string,gauge?:number}) { return <article className="metric"><div className={`metric-icon ${tone||''}`}><Icon size={19}/></div><div><span>{label}</span><strong>{value}</strong><small className={tone==='bad'?'red':''}>{detail}</small></div>{gauge&&<div className="mini-gauge"><i style={{width:`${gauge}%`}}/></div>}</article> }
function TestRow({test,result,running}:{test:Test,result?:Result,running:boolean}) { const meta=kindMeta[test.kind], Icon=meta.icon; return <div className="test-row"><div className={`test-icon ${meta.className}`}><Icon size={18}/></div><div className="test-name"><strong>{test.name}</strong><span>{meta.label} · {test.critical?'Release blocking':'Advisory'}</span></div><div className="target">{test.target.replace(/^https?:\/\//,'')}</div><div className="latency">{result?`${result.latency}ms`:'—'}</div><div className={`status ${result?.status|| (running?'running':'idle')}`}>{result?.status==='passed'?<Check size={14}/>:result?.status==='failed'?<X size={14}/>:<span/>}{result?.status|| (running?'running':'ready')}</div></div> }
function Signal({icon:Icon,title,detail,value}:{icon:typeof Activity,title:string,detail:string,value:string}) { return <div className="signal"><span><Icon size={17}/></span><div><strong>{title}</strong><small>{detail}</small></div><em>{value}</em></div> }

function ServicesDashboard({data,loading,error,refresh,runMonitor}:{data:MonitorsResponse|null,loading:boolean,error:string,refresh:()=>void,runMonitor:(id:string)=>Promise<void>}) {
  const [runningId,setRunningId]=useState('');
  if (loading && !data) return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Loading service monitors…</strong><span>Reading schedules, results, and persistent history.</span></div></section>;
  if (error && !data) return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Service monitoring unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if (!data) return null;
  const up = data.monitors.filter(monitor => monitor.lastResult?.status === 'up').length; const down = data.monitors.filter(monitor => monitor.lastResult?.status === 'down').length;
  const scores = data.monitors.map(monitor => monitor.healthScore).filter((score):score is number => score !== null); const overall = scores.length ? Math.round(scores.reduce((sum,score) => sum + score,0) / scores.length) : null;
  async function run(id:string) { setRunningId(id); try { await runMonitor(id); } finally { setRunningId(''); } }
  return <section className="content infrastructure-content">
    <div className="inventory-banner services-banner"><div><span className={`source-badge ${data.mode === 'live' ? 'proxmox' : 'simulation'}`}>{data.mode === 'live' ? 'LIVE CHECKS' : 'SIMULATION'}</span><strong>Application and service health</strong><p>{data.mode === 'live' ? 'Scheduled outbound checks are enabled.' : 'Safe simulated results are active. Set SENTINEL_REAL_CHECKS=true to enable network checks.'}</p></div></div>
    {error && <div className="inline-error"><CircleAlert size={15}/>{error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Health score" value={overall === null ? '—' : `${overall}%`} detail="Availability plus response time" icon={Gauge} tone={overall !== null && overall < 80 ? 'bad' : 'good'}/><Metric label="Services up" value={String(up)} detail="Latest check succeeded" icon={Check} tone="good"/><Metric label="Services down" value={String(down)} detail={down ? 'Requires investigation' : 'No current failures'} icon={CircleAlert} tone={down ? 'bad' : 'good'}/><Metric label="Scheduled checks" value={String(data.monitors.length)} detail="HTTP, TCP, and DNS" icon={Timer}/></div>
    <section className="panel monitors-panel"><div className="panel-head"><div><h2>Service monitors</h2><p>Automatic checks with persistent result history</p></div><span className="resource-count">30 sec minimum interval</span></div>{data.monitors.length ? <div className="monitor-list">{data.monitors.map(monitor => <MonitorRow key={monitor.id} monitor={monitor} running={runningId===monitor.id} run={() => run(monitor.id)}/>)}</div> : <div className="empty-monitors"><Activity/><strong>No monitors configured</strong><span>Add an HTTP, TCP, or DNS check to begin monitoring.</span></div>}</section>
  </section>;
}

function MonitorRow({monitor,running,run}:{monitor:Monitor,running:boolean,run:()=>void}) {
  const Icon = monitor.protocol === 'http' ? Globe2 : monitor.protocol === 'tcp' ? Cable : Network; const status = monitor.lastResult?.status || 'pending';
  return <article className="monitor-row"><span className={`monitor-protocol ${monitor.protocol}`}><Icon size={17}/></span><div className="monitor-name"><strong>{monitor.name}</strong><small>{monitor.protocol.toUpperCase()} · {monitor.target}</small></div><div className="monitor-stat"><span>UPTIME</span><strong>{monitor.uptimePercent === null ? '—' : `${monitor.uptimePercent}%`}</strong></div><div className="monitor-stat"><span>HEALTH</span><strong>{monitor.healthScore === null ? '—' : `${monitor.healthScore}%`}</strong></div><div className="monitor-stat"><span>LATENCY</span><strong>{monitor.lastResult ? `${monitor.lastResult.latencyMs}ms` : '—'}</strong></div><span className={`monitor-status ${status}`}><i/>{status}</span><button className="monitor-run" onClick={run} disabled={running}>{running ? 'Running…' : 'Run'}</button><div className="monitor-detail">Every {monitor.intervalSeconds}s · {monitor.lastResult ? `${monitor.lastResult.detail} · ${new Date(monitor.lastResult.checkedAt).toLocaleTimeString()}` : 'Waiting for first result'}</div></article>;
}

function MetricsDashboard({data,loading,error,range,selectRange}:{data:MetricsSnapshot|null,loading:boolean,error:string,range:MetricRange,selectRange:(range:MetricRange)=>Promise<void>}) {
  const ranges:MetricRange[]=['1h','6h','24h','7d','30d'];
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Aggregating monitor history…</strong><span>Calculating availability, latency, and time buckets.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Metrics unavailable</strong><span>{error}</span></div></section>;
  if(!data)return null;
  return <section className="content infrastructure-content metrics-content">
    <div className="inventory-banner metrics-banner"><div><span className="source-badge proxmox">TIME SERIES</span><strong>Service health history</strong><p>{data.retainedResults.toLocaleString()} results retained for up to {data.retention.days} days. Prometheus can scrape current gauges from <code>GET /metrics</code>.</p></div><div className="range-picker">{ranges.map(item=><button key={item} className={range===item?'active':''} disabled={loading} onClick={()=>selectRange(item)}>{item}</button>)}</div></div>
    {error&&<div className="inline-error"><CircleAlert size={15}/>{error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Availability" value={data.overall.availabilityPercent===null?'—':`${data.overall.availabilityPercent}%`} detail={`${data.overall.checks} checks in range`} icon={ShieldCheck} tone={data.overall.availabilityPercent!==null&&data.overall.availabilityPercent<99?'bad':'good'}/><Metric label="Average latency" value={data.overall.avgLatencyMs===null?'—':`${data.overall.avgLatencyMs}ms`} detail="Across all service checks" icon={Timer}/><Metric label="P95 latency" value={data.overall.p95LatencyMs===null?'—':`${data.overall.p95LatencyMs}ms`} detail="95% of checks at or below" icon={Gauge}/><Metric label="Failed checks" value={String(data.overall.failures)} detail={data.overall.failures?'Failures require review':'No failures in this range'} icon={CircleAlert} tone={data.overall.failures?'bad':'good'}/></div>
    <section className="panel trends-panel"><div className="panel-head"><div><h2>Monitor trends</h2><p>Bucketed response time with failure markers</p></div><span className="resource-count">{formatBucket(data.bucketSeconds)} buckets</span></div><div className="trend-grid">{data.series.map(series=><article className="trend-card" key={series.monitorId}><div className="trend-head"><div><strong>{series.name}</strong><small>{series.protocol.toUpperCase()} · {series.summary.checks} checks</small></div><span className={`monitor-status ${series.currentStatus}`}><i/>{series.currentStatus}</span></div><div className="trend-summary"><span>Uptime <strong>{series.summary.availabilityPercent===null?'—':`${series.summary.availabilityPercent}%`}</strong></span><span>Average <strong>{series.summary.avgLatencyMs===null?'—':`${series.summary.avgLatencyMs}ms`}</strong></span><span>P95 <strong>{series.summary.p95LatencyMs===null?'—':`${series.summary.p95LatencyMs}ms`}</strong></span></div><MetricTrend points={series.points} name={series.name}/></article>)}</div></section>
    <div className="metrics-footer"><section className="panel retention-card"><Database/><div><strong>Retention policy</strong><p>Keep results for {data.retention.days} days, capped at {data.retention.maxResults.toLocaleString()} records. Old data is pruned during collection and whenever the policy changes.</p></div></section><section className="panel prometheus-card"><LineChart/><div><strong>Prometheus export</strong><p>Current status, latency, health score, uptime, incidents, rules, mode, and retained-result count are exposed in Prometheus text format.</p><code>http://sentinel-host:4100/metrics</code></div></section></div>
  </section>;
}

function MetricTrend({points,name}:{points:MetricPoint[],name:string}) {
  const values=points.map(point=>point.avgLatencyMs); const valid=values.filter((value):value is number=>value!==null); if(!valid.length)return <div className="empty-trend">Waiting for checks in this time range</div>;
  const max=Math.max(...valid,1);const x=(index:number)=>points.length===1?300:(index/(points.length-1))*600;const y=(value:number)=>125-(value/max)*100;const segments:string[]=[];let current:string[]=[];
  values.forEach((value,index)=>{if(value===null){if(current.length)segments.push(current.join(' '));current=[];}else current.push(`${x(index)},${y(value)}`)});if(current.length)segments.push(current.join(' '));
  return <svg className="metric-trend" viewBox="0 0 600 140" preserveAspectRatio="none" role="img" aria-label={`${name} latency trend`}><line x1="0" y1="25" x2="600" y2="25"/><line x1="0" y1="75" x2="600" y2="75"/><line x1="0" y1="125" x2="600" y2="125"/>{segments.map((segment,index)=><polyline key={index} points={segment}/>)}{points.map((point,index)=>point.avgLatencyMs!==null?<circle className={point.failures?'failure':'sample'} key={point.timestamp} cx={x(index)} cy={y(point.avgLatencyMs)} r={point.failures?5:3}/>:null)}</svg>;
}

function PerformanceDashboard({data,loading,error,range,selectRange}:{data:TelemetrySnapshot|null,loading:boolean,error:string,range:MetricRange,selectRange:(range:MetricRange)=>Promise<void>}) {
  const ranges:MetricRange[]=['1h','6h','24h','7d','30d'];
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Collecting infrastructure telemetry…</strong><span>Reading CPU, memory, disk, and network utilization.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Infrastructure metrics unavailable</strong><span>{error}</span></div></section>;
  if(!data)return null;
  const average=(values:number[])=>values.length?Math.round(values.reduce((sum,value)=>sum+value,0)/values.length):0;
  return <section className="content infrastructure-content metrics-content">
    <div className="inventory-banner metrics-banner"><div><span className="source-badge proxmox">RESOURCE TELEMETRY</span><strong>Proxmox and Docker performance</strong><p>CPU, memory, disk capacity, network throughput, and container block I/O are retained as time-series samples.</p></div><div className="range-picker">{ranges.map(item=><button key={item} className={range===item?'active':''} disabled={loading} onClick={()=>selectRange(item)}>{item}</button>)}</div></div>
    {error&&<div className="inline-error"><CircleAlert size={15}/>{error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Resources" value={String(data.summary.resources)} detail={`${data.summary.proxmoxResources} Proxmox · ${data.summary.containers} containers`} icon={Server}/><Metric label="Average CPU" value={`${average(data.series.map(item=>item.latest.cpuPercent))}%`} detail="Current utilization across resources" icon={Gauge}/><Metric label="Average memory" value={`${average(data.series.map(item=>item.latest.memoryPercent||0))}%`} detail="Current assigned-memory usage" icon={Database}/><Metric label="Capacity warnings" value={String(data.summary.warningResources)} detail={data.summary.warningResources?'CPU, memory, or disk threshold exceeded':'All resources within thresholds'} icon={CircleAlert} tone={data.summary.warningResources?'bad':'good'}/></div>
    <section className="panel trends-panel"><div className="panel-head"><div><h2>Resource utilization</h2><p>Latest capacity and historical CPU trend</p></div><span className="resource-count">{formatBucket(data.bucketSeconds)} buckets</span></div><div className="trend-grid">{data.series.map(series=><article className="trend-card" key={series.resourceId}><div className="trend-head"><div><strong>{series.name}</strong><small>{series.source.toUpperCase()} · {series.type.toUpperCase()} · {series.state}</small></div><span className={`health-badge ${series.latest.cpuPercent>=85||(series.latest.memoryPercent||0)>=90?'warning':'healthy'}`}><i/>{series.latest.cpuPercent>=85||(series.latest.memoryPercent||0)>=90?'warning':'healthy'}</span></div><div className="trend-summary"><span>CPU <strong>{series.latest.cpuPercent}%</strong></span><span>Memory <strong>{series.latest.memoryPercent===null?'—':`${series.latest.memoryPercent}%`}</strong></span><span>Disk <strong>{series.latest.diskPercent===null?'—':`${series.latest.diskPercent}%`}</strong></span><span>Network <strong>{formatBytes((series.latest.networkRxBytesPerSecond||0)+(series.latest.networkTxBytesPerSecond||0))}/s</strong></span></div><ResourceTrend points={series.points} name={series.name}/></article>)}</div></section>
  </section>;
}

function ResourceTrend({points,name}:{points:TelemetryPoint[],name:string}) {
  const values=points.map(point=>point.cpuPercent);const valid=values.filter((value):value is number=>value!==null);if(!valid.length)return <div className="empty-trend">Waiting for telemetry in this time range</div>;
  const x=(index:number)=>points.length===1?300:(index/(points.length-1))*600;const y=(value:number)=>125-(Math.min(value,100)/100)*100;const segments:string[]=[];let current:string[]=[];values.forEach((value,index)=>{if(value===null){if(current.length)segments.push(current.join(' '));current=[]}else current.push(`${x(index)},${y(value)}`)});if(current.length)segments.push(current.join(' '));
  return <svg className="metric-trend" viewBox="0 0 600 140" preserveAspectRatio="none" role="img" aria-label={`${name} CPU utilization trend`}><line x1="0" y1="25" x2="600" y2="25"/><line x1="0" y1="75" x2="600" y2="75"/><line x1="0" y1="125" x2="600" y2="125"/>{segments.map((segment,index)=><polyline key={index} points={segment}/>)}</svg>;
}

function LogsDashboard({data,loading,error,incidents,search}:{data:LogSearchResult|null,loading:boolean,error:string,incidents:Incident[],search:(filters:{range?:LogRange;level?:string;source?:string;search?:string})=>Promise<void>}) {
  const [range,setRange]=useState<LogRange>(data?.range||'1h');const [level,setLevel]=useState('all');const [source,setSource]=useState('all');const [text,setText]=useState('');const [correlation,setCorrelation]=useState<IncidentLogCorrelation|null>(null);const [correlationError,setCorrelationError]=useState('');const [investigating,setInvestigating]=useState('');
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Querying centralized logs…</strong><span>Searching Loki streams and CMDB-aware labels.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Logs unavailable</strong><span>{error}</span></div></section>;
  if(!data)return null;const sources=[...new Set(data.entries.map(item=>item.source))].sort();
  async function investigate(id:string){setInvestigating(id);setCorrelationError('');try{const response=await fetch(`/api/logs/incidents/${encodeURIComponent(id)}/correlation`);if(!response.ok)throw new Error(await apiError(response));setCorrelation(await response.json())}catch(value){setCorrelationError(value instanceof Error?value.message:'Unable to correlate incident logs')}finally{setInvestigating('')}}
  return <section className="content infrastructure-content logs-content">
    <div className="inventory-banner"><div><span className={`source-badge ${data.mode==='live'?'proxmox':'simulation'}`}>{data.mode==='live'?'LIVE LOKI':'SIMULATION'}</span><strong>Centralized log investigation</strong><p>Search Docker, system journal, network syslog, hardware, and application events using stable CMDB identifiers.</p></div><small>{data.entries.length} results · {data.range} window</small></div>
    {error&&<div className="inline-error"><CircleAlert size={15}/>{error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Matching events" value={String(data.summary.total)} detail={`${data.summary.sources} sources · ${data.summary.services} services`} icon={Braces}/><Metric label="Errors" value={String(data.summary.errors)} detail={data.summary.errors?'Errors need investigation':'No errors in this view'} icon={CircleAlert} tone={data.summary.errors?'bad':'good'}/><Metric label="Warnings" value={String(data.summary.warnings)} detail="Potential degradation signals" icon={Timer}/><Metric label="CMDB-linked" value={String(data.entries.filter(item=>item.ciId).length)} detail="Events tied to configuration items" icon={Link2}/></div>
    <section className="panel log-search-panel"><form className="log-filters" onSubmit={event=>{event.preventDefault();void search({range,level,source,search:text})}}><div className="search"><Search size={15}/><input value={text} onChange={event=>setText(event.target.value)} placeholder="Search log messages"/></div><select value={range} onChange={event=>setRange(event.target.value as LogRange)}><option value="15m">Last 15 minutes</option><option value="1h">Last hour</option><option value="6h">Last 6 hours</option><option value="24h">Last 24 hours</option><option value="7d">Last 7 days</option></select><select value={level} onChange={event=>setLevel(event.target.value)}><option value="all">All levels</option><option value="critical">Critical</option><option value="error">Error</option><option value="warn">Warning</option><option value="info">Info</option><option value="debug">Debug</option></select><select value={source} onChange={event=>setSource(event.target.value)}><option value="all">All sources</option>{sources.map(value=><option value={value} key={value}>{value}</option>)}</select><button className="primary" disabled={loading}><Search size={14}/>{loading?'Searching…':'Search'}</button></form></section>
    <div className="logs-grid"><section className="panel log-results"><div className="panel-head"><div><h2>Log stream</h2><p>Newest matching entries first</p></div><code>{data.query}</code></div><div className="log-list">{data.entries.length?data.entries.map(entry=><article className="log-row" key={entry.id}><span className={`log-level ${entry.level}`}>{entry.level}</span><time>{new Date(entry.timestamp).toLocaleTimeString()}</time><div><strong>{entry.message}</strong><small>{entry.service||entry.host||'Unknown service'} · {entry.source}{entry.ciId?` · ${entry.ciId}`:''}</small></div></article>):<div className="empty-monitors"><Search/><strong>No matching logs</strong><span>Broaden the time window or remove one of the filters.</span></div>}</div></section>
      <aside className="log-side"><section className="panel"><div className="panel-head"><div><h2>Incident investigation</h2><p>Retrieve logs from related CIs</p></div></div><div className="incident-log-list">{incidents.length?incidents.map(incident=><div key={incident.id}><span className={`incident-severity ${incident.severity}`}>{incident.severity}</span><div><strong>{incident.title}</strong><small>{relativeTime(incident.openedAt)}</small></div><button className="monitor-run" disabled={investigating===incident.id} onClick={()=>investigate(incident.id)}>{investigating===incident.id?'Querying…':'Investigate'}</button></div>):<div className="empty-resource">No active incidents to investigate.</div>}</div></section>{(correlation||correlationError)&&<section className="panel correlation-logs"><div className="panel-head"><div><h2>Correlated evidence</h2><p>{correlation?.incident.title||'Investigation failed'}</p></div></div>{correlationError?<div className="inline-error"><CircleAlert size={14}/>{correlationError}</div>:<><div className="correlation-ci">{correlation?.relatedConfigurationItems.map(item=><span key={item}>{item}</span>)}</div><div className="correlation-log-list">{correlation?.entries.slice(0,8).map(entry=><div key={entry.id}><span className={`log-level ${entry.level}`}>{entry.level}</span><p>{entry.message}</p></div>)}{!correlation?.entries.length&&<div className="empty-resource">No related logs found in the six-hour window.</div>}</div></>}</section>}</aside>
    </div>
  </section>;
}

function CollectorsDashboard({data,loading,error,admin,refresh,enroll,rotate,remove}:{data:CollectorDashboardSnapshot|null,loading:boolean,error:string,admin:boolean,refresh:()=>Promise<void>,enroll:(input:{name:string;site:string;kind:CollectorKind;intervalSeconds:number})=>Promise<string>,rotate:(id:string)=>Promise<string>,remove:(id:string)=>Promise<void>}){
  const[site,setSite]=useState('all');const[name,setName]=useState('');const[newSite,setNewSite]=useState('');const[kind,setKind]=useState<CollectorKind>('hybrid');const[token,setToken]=useState('');const[actionError,setActionError]=useState('');const[busy,setBusy]=useState(false);
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Loading remote sites…</strong><span>Checking collector heartbeats and retained inventories.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Collector status unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if(!data)return null;const visible=site==='all'?data.collectors:data.collectors.filter(item=>item.site===site);
  async function register(event:React.FormEvent){event.preventDefault();setBusy(true);setActionError('');try{setToken(await enroll({name,site:newSite,kind,intervalSeconds:60}));setName('');setNewSite('')}catch(value){setActionError(value instanceof Error?value.message:'Unable to enroll collector')}finally{setBusy(false)}}
  async function rotateToken(id:string){setBusy(true);setActionError('');try{setToken(await rotate(id))}catch(value){setActionError(value instanceof Error?value.message:'Unable to rotate token')}finally{setBusy(false)}}
  async function deleteCollector(id:string){if(!window.confirm('Remove this collector and revoke its token?'))return;setBusy(true);setActionError('');try{await remove(id)}catch(value){setActionError(value instanceof Error?value.message:'Unable to remove collector')}finally{setBusy(false)}}
  return <section className="content infrastructure-content collectors-content">
    <div className="inventory-banner collectors-banner"><div><span className="source-badge proxmox">DISTRIBUTED</span><strong>Remote sites and collectors</strong><p>Outbound-only agents report Proxmox and Docker inventory without exposing remote management interfaces.</p></div><small>{data.summary.sites} sites · {data.summary.resources} remote resources</small></div>
    {(error||actionError)&&<div className="inline-error"><CircleAlert size={15}/>{actionError||error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Collectors" value={String(data.summary.collectors)} detail={`${data.summary.sites} registered sites`} icon={Radio}/><Metric label="Online" value={String(data.summary.online)} detail="Reporting within heartbeat window" icon={Activity} tone="good"/><Metric label="Missed heartbeat" value={String(data.summary.stale+data.summary.never)} detail="Stale or never connected" icon={CircleAlert} tone={data.summary.stale+data.summary.never?'bad':'good'}/><Metric label="Remote resources" value={String(data.summary.resources)} detail={`${data.summary.warnings} warnings or errors`} icon={Boxes} tone={data.summary.warnings?'bad':undefined}/></div>
    <div className="collector-layout"><section className="panel site-panel"><div className="panel-head"><div><h2>Site inventory</h2><p>Consolidated Proxmox and Docker footprint</p></div><select value={site} onChange={event=>setSite(event.target.value)}><option value="all">All sites</option>{data.sites.map(item=><option key={item.name}>{item.name}</option>)}</select></div><div className="site-grid">{data.sites.map(item=><button className={site===item.name?'selected':''} key={item.name} onClick={()=>setSite(item.name)}><Globe2/><span><strong>{item.name}</strong><small>{item.online}/{item.collectors} collectors online</small></span><em>{item.nodes} nodes · {item.virtualMachines} VMs · {item.lxcContainers} LXC · {item.dockerContainers} containers</em></button>)}</div></section>
    {admin&&<section className="panel enroll-panel"><div className="panel-head"><div><h2>Enroll collector</h2><p>The token is displayed once</p></div></div><form onSubmit={register}><label>Name<input required value={name} onChange={event=>setName(event.target.value)} placeholder="Basement collector"/></label><label>Site<input required value={newSite} onChange={event=>setNewSite(event.target.value)} placeholder="Home lab"/></label><label>Sources<select value={kind} onChange={event=>setKind(event.target.value as CollectorKind)}><option value="hybrid">Proxmox + Docker</option><option value="proxmox">Proxmox</option><option value="docker">Docker</option></select></label><button className="primary" disabled={busy}><Plus size={14}/>{busy?'Working…':'Enroll'}</button></form>{token&&<div className="collector-token"><strong>Copy this token now</strong><code>{token}</code><small>It cannot be displayed again.</small></div>}</section>}</div>
    <section className="panel collector-panel"><div className="panel-head"><div><h2>Collectors</h2><p>Heartbeat, version, inventory, and delivery state</p></div><span className="resource-count">{visible.length} shown</span></div><div className="collector-list">{visible.length?visible.map(item=><article key={item.id}><span className={item.status}><Radio/></span><div><strong>{item.name}</strong><small>{item.site} · {item.kind} · version {item.version||'not reported'}</small></div><div className="collector-resources"><strong>{item.summary.proxmoxResources+item.summary.dockerContainers}</strong><small>resources</small></div><div><em className={item.status}>{item.status}</em><small>{item.lastSeenAt?relativeTime(item.lastSeenAt):'Awaiting first report'}</small></div>{admin&&<div className="collector-actions"><button disabled={busy} onClick={()=>rotateToken(item.id)}>Rotate</button><button disabled={busy} onClick={()=>deleteCollector(item.id)}><Trash2 size={13}/></button></div>}</article>):<div className="empty-incidents"><Globe2/><strong>No collectors enrolled</strong><span>Register the first site collector to begin remote discovery.</span></div>}</div></section>
  </section>;
}

function AutomationDashboard({data,serviceNow,cis,incidents,loading,error,operate,refresh,retry,syncCmdb,createChange}:{data:AutomationSnapshot|null,serviceNow:ServiceNowCmdbSnapshot|null,cis:ConfigurationItem[],incidents:Incident[],loading:boolean,error:string,operate:boolean,refresh:()=>Promise<void>,retry:(id:string)=>Promise<void>,syncCmdb:()=>Promise<void>,createChange:(input:{ciId:string;shortDescription:string;description:string;startsAt:string;endsAt:string;riskAnalysis:string})=>Promise<ServiceNowChange>}) {
  const [busy,setBusy]=useState('');const [actionError,setActionError]=useState('');const [changeOpen,setChangeOpen]=useState(false);
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Loading automation history…</strong><span>Reading configured routes, tickets, and delivery attempts.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Automation unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if(!data)return null;
  const routes=[['Generic webhook',data.status.webhookConfigured],['Slack',data.status.slackConfigured],['Microsoft Teams',data.status.teamsConfigured],['Email',data.status.emailConfigured],['ServiceNow',data.status.serviceNowConfigured]] as const;
  const title=(id:string)=>incidents.find(item=>item.id===id)?.title||id;
  async function run(id:string){setBusy(id);setActionError('');try{await retry(id)}catch(value){setActionError(value instanceof Error?value.message:'Retry failed')}finally{setBusy('')}}
  async function sync(){setBusy('cmdb-sync');setActionError('');try{await syncCmdb()}catch(value){setActionError(value instanceof Error?value.message:'CMDB sync failed')}finally{setBusy('')}}
  return <section className="content infrastructure-content automation-content">
    <div className="inventory-banner automation-banner"><div><span className={`source-badge ${data.status.mode==='live'?'proxmox':'simulation'}`}>{data.status.mode==='live'?'LIVE AUTOMATION':'SIMULATION'}</span><strong>Incident integrations and delivery control</strong><p>Route alert lifecycles to chat, email, generic systems, and correlated ServiceNow incidents. Failed attempts remain visible and operator-retryable.</p></div><small>{routes.filter(([,ready])=>ready).length} of {routes.length} routes configured</small></div>
    {(error||actionError)&&<div className="inline-error"><CircleAlert size={15}/>{actionError||error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Successful deliveries" value={String(data.summary.sent)} detail="Newest 100 attempts" icon={Check} tone="good"/><Metric label="Failed deliveries" value={String(data.summary.failed)} detail={data.summary.failed?'Operator retry available':'No delivery failures'} icon={CircleAlert} tone={data.summary.failed?'bad':'good'}/><Metric label="ServiceNow tickets" value={String(data.summary.tickets)} detail="Correlated incident records" icon={Database}/><Metric label="Simulation records" value={String(data.summary.simulated)} detail={data.status.mode==='live'?'Historical dry runs':'No external calls are sent'} icon={Workflow}/></div>
    <div className="automation-grid"><section className="panel route-panel"><div className="panel-head"><div><h2>Delivery routes</h2><p>Configuration is loaded from protected environment values or secret files</p></div></div><div className="route-list">{routes.map(([name,ready])=><div key={name}><span className={ready?'ready':'setup'}>{ready?<Check/>:<Settings/>}</span><strong>{name}</strong><em>{ready?'ready':'setup required'}</em></div>)}</div></section><section className="panel ticket-panel"><div className="panel-head"><div><h2>External tickets</h2><p>One ServiceNow record per Sentinel incident</p></div></div><div className="ticket-list">{incidents.filter(item=>item.externalTicket).slice(0,8).map(item=><div key={item.id}><Database/><span><strong>{item.externalTicket!.number}</strong><small>{item.title} · {item.status}</small></span>{item.externalTicket?.url&&<a href={item.externalTicket.url} target="_blank" rel="noreferrer">Open</a>}</div>)}{!incidents.some(item=>item.externalTicket)&&<div className="empty-incidents"><Database/><strong>No synchronized tickets</strong><span>Tickets appear after live ServiceNow delivery opens an incident.</span></div>}</div></section></div>
    {serviceNow&&<ServiceNowCmdbPanel data={serviceNow} cis={cis} operate={operate} busy={busy} sync={sync} openChange={()=>setChangeOpen(true)}/>}
    <section className="panel delivery-panel"><div className="panel-head"><div><h2>Delivery history</h2><p>Channel, event, result, and retry lineage</p></div><span className="resource-count">{data.deliveries.length} retained</span></div><div className="delivery-list">{data.deliveries.length?data.deliveries.map(item=><article key={item.id}><span className={item.status}>{item.status==='sent'?<Check/>:item.status==='failed'?<CircleAlert/>:<Workflow/>}</span><div><strong>{title(item.incidentId)}</strong><small>{item.channel} · {item.event} · attempt {item.attempt||1} · {relativeTime(item.attemptedAt)}</small><p>{item.detail}</p></div><em className={item.status}>{item.status}</em>{item.status==='failed'&&operate&&<button className="monitor-run" disabled={busy===item.id} onClick={()=>run(item.id)}>{busy===item.id?'Retrying…':'Retry'}</button>}</article>):<div className="empty-incidents"><Workflow/><strong>No deliveries recorded</strong><span>Alert events will create delivery records here.</span></div>}</div></section>
    {changeOpen&&<ServiceNowChangeModal cis={cis} close={()=>setChangeOpen(false)} save={async input=>{setBusy('change');setActionError('');try{await createChange(input);setChangeOpen(false)}catch(value){setActionError(value instanceof Error?value.message:'Change creation failed');throw value}finally{setBusy('')}}}/>}
  </section>;
}

function ServiceNowCmdbPanel({data,cis,operate,busy,sync,openChange}:{data:ServiceNowCmdbSnapshot,cis:ConfigurationItem[],operate:boolean,busy:string,sync:()=>Promise<void>,openChange:()=>void}){
  const last=data.status.lastRun;const mapped=data.mappings.filter(item=>item.sysId).length;const ciName=(id:string)=>cis.find(item=>item.id===id)?.name||id;
  return <section className="panel snow-cmdb-panel"><div className="panel-head"><div><h2>ServiceNow configuration management</h2><p>Identification and Reconciliation Engine sync with CI relationships and stable source keys</p></div><span className={`source-badge ${data.status.mode==='live'?'proxmox':'simulation'}`}>{data.status.mode==='live'?'LIVE IRE':'DRY RUN'}</span></div>
    <div className="snow-summary"><div><small>CI mappings</small><strong>{mapped}<span> / {data.status.mappings}</span></strong></div><div><small>Latest sync</small><strong>{last?last.status:'Not run'}</strong><em>{last?relativeTime(last.finishedAt):`Every ${data.status.intervalMinutes} minutes`}</em></div><div><small>Latest result</small><strong>{last?`${last.inserted} new · ${last.updated} updated`:'Awaiting preview'}</strong><em>{last?`${last.relationships} relationships · ${last.failed} failed`:`Source: ${data.status.source}`}</em></div><div><small>Changes</small><strong>{data.changes.length}</strong><em>{data.status.autoChanges?'Maintenance auto-change on':'Manual creation'}</em></div></div>
    <div className="snow-actions"><div><ShieldCheck/><span><strong>{data.status.configured?'Credentials configured':'Credentials not required for preview'}</strong><small>{data.status.feed} feed · retired CIs excluded</small></span></div>{operate&&<><button className="secondary" onClick={openChange} disabled={!cis.length}><Plus size={14}/>Planned change</button><button className="primary" onClick={sync} disabled={busy==='cmdb-sync'}><RefreshCw className={busy==='cmdb-sync'?'spin':''} size={14}/>{busy==='cmdb-sync'?'Synchronizing…':data.status.mode==='live'?'Sync now':'Preview sync'}</button></>}</div>
    <div className="snow-detail-grid"><div><h3>Recent synchronization</h3>{data.runs.length?<div className="snow-run-list">{data.runs.slice(0,5).map(run=><article key={run.id}><span className={run.status}><Database/></span><div><strong>{run.mode==='live'?'IRE synchronization':'Local preview'}</strong><small>{new Date(run.finishedAt).toLocaleString()} · {run.items} CIs · {run.relationships} relationships</small></div><em>{run.status}</em></article>)}</div>:<p className="snow-empty">Run a preview to validate the outbound scope without contacting ServiceNow.</p>}</div><div><h3>Recent planned changes</h3>{data.changes.length?<div className="snow-change-list">{data.changes.slice(0,5).map(change=><article key={change.id}><span><Workflow/></span><div><strong>{change.number} · {change.shortDescription}</strong><small>{ciName(change.ciId)} · {new Date(change.startsAt).toLocaleString()}</small></div>{change.url?<a href={change.url} target="_blank" rel="noreferrer">Open</a>:<em>{change.status}</em>}</article>)}</div>:<p className="snow-empty">No ServiceNow changes have been created from Sentinel.</p>}</div></div>
  </section>
}

function ServiceNowChangeModal({cis,close,save}:{cis:ConfigurationItem[],close:()=>void,save:(input:{ciId:string;shortDescription:string;description:string;startsAt:string;endsAt:string;riskAnalysis:string})=>Promise<void>}){
  const start=new Date(Date.now()+60*60*1000);const end=new Date(start.getTime()+2*60*60*1000);const local=(value:Date)=>new Date(value.getTime()-value.getTimezoneOffset()*60_000).toISOString().slice(0,16);
  const [ciId,setCiId]=useState(cis[0]?.id||'');const [shortDescription,setShortDescription]=useState('Planned Sentinel maintenance');const [description,setDescription]=useState('Planned maintenance coordinated from SentinelLab.');const [startsAt,setStartsAt]=useState(local(start));const [endsAt,setEndsAt]=useState(local(end));const [riskAnalysis,setRiskAnalysis]=useState('Validated monitoring coverage and rollback plan before execution.');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');try{await save({ciId,shortDescription,description,startsAt:new Date(startsAt).toISOString(),endsAt:new Date(endsAt).toISOString(),riskAnalysis})}catch(value){setError(value instanceof Error?value.message:'Unable to create change');setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)close()}}><form className="modal snow-change-modal" onSubmit={submit}><div className="modal-title"><div><span className="modal-icon"><Workflow/></span><div><h2>Create planned change</h2><p>Link an operational window to a synchronized configuration item</p></div></div><button type="button" onClick={close}><X/></button></div>{error&&<div className="inline-error"><CircleAlert size={14}/>{error}</div>}<div className="form-grid"><label className="full">Configuration item<select required value={ciId} onChange={event=>setCiId(event.target.value)}>{cis.filter(item=>item.lifecycle!=='retired').map(item=><option key={item.id} value={item.id}>{item.name} · {item.class}</option>)}</select></label><label className="full">Short description<input required maxLength={40} value={shortDescription} onChange={event=>setShortDescription(event.target.value)}/></label><label>Starts<input required type="datetime-local" value={startsAt} onChange={event=>setStartsAt(event.target.value)}/></label><label>Ends<input required type="datetime-local" value={endsAt} onChange={event=>setEndsAt(event.target.value)}/></label><label className="full">Implementation detail<textarea required value={description} onChange={event=>setDescription(event.target.value)}/></label><label className="full">Risk and rollback<textarea required value={riskAnalysis} onChange={event=>setRiskAnalysis(event.target.value)}/></label></div><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={busy||!ciId}><Workflow size={15}/>{busy?'Creating…':'Create change'}</button></div></form></div>
}

function RecoveryDashboard({data,loading,error,refresh,verify,replicate}:{data:BackupSnapshot|null,loading:boolean,error:string,refresh:()=>Promise<void>,verify:(id:string)=>Promise<void>,replicate:(id:string)=>Promise<void>}) {
  const [verifying,setVerifying]=useState('');
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Loading recovery state…</strong><span>Reading retained backups and verification manifests.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Recovery status unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if(!data)return null;
  async function check(id:string){setVerifying(id);try{await verify(id)}finally{setVerifying('')}}
  async function copy(id:string){setVerifying(id);try{await replicate(id)}finally{setVerifying('')}}
  const latest=data.backups[0];
  return <section className="content infrastructure-content recovery-content">
    <div className="inventory-banner recovery-banner"><div><span className={`source-badge ${data.enabled?'proxmox':'simulation'}`}>{data.enabled?'SCHEDULED':'MANUAL ONLY'}</span><strong>Backup and disaster recovery</strong><p>Checksummed snapshots contain the SQLite database and every available persistent data store. Restore remains an offline, explicitly confirmed operation.</p></div><small>{data.enabled?`Every ${data.intervalHours} hours`:'Scheduling disabled'} · keep {data.maxBackups}</small></div>
    {(error||data.lastError)&&<div className="inline-error"><CircleAlert size={15}/>{error||data.lastError}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Retained backups" value={String(data.summary.count)} detail={`Maximum ${data.maxBackups}`} icon={HardDrive}/><Metric label="Verified" value={String(data.summary.verified)} detail={data.summary.verified===data.summary.count?'All checksums valid':'Verification required'} icon={ShieldCheck} tone={data.summary.verified===data.summary.count?'good':'bad'}/><Metric label="Replicated" value={data.replicaConfigured?String(data.summary.replicated):'Not set'} detail={data.replicaConfigured?'Verified on external target':'Mount a separate NAS or volume'} icon={Network} tone={data.replicaConfigured&&data.summary.replicated===data.summary.count?'good':undefined}/><Metric label="Latest backup" value={latest?relativeTime(latest.createdAt):'Never'} detail={latest?`${formatBytes(latest.bytes)} · ${latest.files} files`:'Create the first recovery point'} icon={Timer}/></div>
    <section className="panel backup-panel"><div className="panel-head"><div><h2>Recovery points</h2><p>Transactional database snapshots with SHA-256 verification</p></div><span className="resource-count">Offline restore required</span></div><div className="backup-list">{data.backups.length?data.backups.map(backup=><article key={backup.id}><span className={backup.verified?'verified':'failed'}>{backup.verified?<Check/>:<CircleAlert/>}</span><div><strong>{backup.id}</strong><small>{new Date(backup.createdAt).toLocaleString()} · {backup.reason} · {backup.files} files · {formatBytes(backup.bytes)}</small>{(backup.error||backup.replicaError)&&<p>{backup.error||backup.replicaError}</p>}{backup.replicated&&<p className="replica-ok">External replica verified</p>}</div><em className={backup.verified?'verified':'failed'}>{backup.verified?'verified':'failed'}</em><button className="monitor-run" disabled={verifying===backup.id} onClick={()=>check(backup.id)}>{verifying===backup.id?'Working…':'Verify'}</button>{data.replicaConfigured&&!backup.replicated&&<button className="monitor-run" disabled={verifying===backup.id} onClick={()=>copy(backup.id)}>Replicate</button>}</article>):<div className="empty-incidents"><HardDrive/><strong>No backups yet</strong><span>Use Back up now to create and verify the first recovery point.</span></div>}</div></section>
    <section className="panel restore-guidance"><ShieldCheck/><div><strong>Safe restore procedure</strong><p>Stop Sentinel, run the restore command with the backup ID repeated as confirmation, then start Sentinel and verify health. The restore automatically copies the current files into a rollback-point directory first.</p><code>node server-dist/backup/restore.js --backup &lt;backup-id&gt; --confirm &lt;backup-id&gt;</code></div></section>
  </section>;
}

function SecurityDashboard({data,loading,error,refresh}:{data:SecuritySnapshot|null,loading:boolean,error:string,refresh:(type?:SecurityEventType)=>Promise<void>}) {
  const [filter,setFilter]=useState<'all'|SecurityEventType>('all');
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Loading security audit…</strong><span>Reading authenticated sessions and rejected access attempts.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Security audit unavailable</strong><span>{error}</span><button className="secondary" onClick={()=>refresh()}>Try again</button></div></section>;
  if(!data)return null;
  async function select(value:'all'|SecurityEventType){setFilter(value);await refresh(value==='all'?undefined:value)}
  return <section className="content infrastructure-content security-content">
    <div className="inventory-banner security-banner"><div><span className="source-badge proxmox">ACCESS CONTROL</span><strong>Authentication and authorization audit</strong><p>Retained evidence from trusted proxy sessions, rejected authentication, and role-based access denials.</p></div><small>{data.retention.days} day retention · {data.retention.maxEvents.toLocaleString()} event limit</small></div>
    {error&&<div className="inline-error"><CircleAlert size={15}/>{error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Authenticated sessions" value={String(data.summary.sessions)} detail="Session checks retained" icon={UserRound} tone="good"/><Metric label="Authentication failures" value={String(data.summary.failures)} detail={data.summary.failures?'Review untrusted requests':'No failed authentication'} icon={CircleAlert} tone={data.summary.failures?'bad':'good'}/><Metric label="Permission denials" value={String(data.summary.denied)} detail={data.summary.denied?'RBAC blocked unsafe actions':'No denied operations'} icon={ShieldCheck} tone={data.summary.denied?'bad':'good'}/><Metric label="Retained events" value={String(data.summary.retained)} detail="Owner-only persistent history" icon={Database}/></div>
    <section className="panel security-events"><div className="panel-head"><div><h2>Access events</h2><p>Newest security evidence first</p></div><div className="security-filters"><select value={filter} onChange={event=>void select(event.target.value as 'all'|SecurityEventType)}><option value="all">All events</option><option value="session_authenticated">Sessions</option><option value="authentication_failed">Authentication failures</option><option value="authorization_denied">Permission denials</option></select><button className="secondary" onClick={()=>refresh(filter==='all'?undefined:filter)} disabled={loading}><RefreshCw className={loading?'spin':''} size={14}/>Refresh</button></div></div><div className="security-event-list">{data.events.length?data.events.map(event=><article className={event.severity} key={event.id}><span>{event.type==='session_authenticated'?<UserRound/>:event.type==='authentication_failed'?<CircleAlert/>:<ShieldCheck/>}</span><div><strong>{event.type.replaceAll('_',' ')}</strong><p>{event.subject||event.reason||'Unauthenticated request'}{event.role?` · ${event.role}`:''}{event.requiredRole?` · required ${event.requiredRole}`:''}</p><small>{event.method} {event.path}{event.sourceIp?` · ${event.sourceIp}`:''}</small></div><time>{new Date(event.timestamp).toLocaleString()}</time></article>):<div className="empty-incidents"><ShieldCheck/><strong>No matching security events</strong><span>Events will appear when users sign in or an access check is rejected.</span></div>}</div></section>
  </section>;
}

function CmdbDashboard({data,loading,error,refresh,edit}:{data:CmdbSnapshot|null,loading:boolean,error:string,refresh:()=>void,edit:(item:ConfigurationItem)=>void}) {
  const [query,setQuery]=useState('');const [classFilter,setClassFilter]=useState('all');
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Reconciling configuration items…</strong><span>Building a trusted inventory from Proxmox, Docker, and service monitoring.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>CMDB unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if(!data)return null;const filtered=data.items.filter(item=>(classFilter==='all'||item.class===classFilter)&&`${item.name} ${item.externalId} ${item.owner} ${item.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));const itemName=(id:string)=>data.items.find(item=>item.id===id)?.name||id;
  return <section className="content infrastructure-content cmdb-content">
    <div className="inventory-banner"><div><span className={`source-badge ${data.status.mode==='live'?'proxmox':'simulation'}`}>{data.status.mode==='live'?'LIVE DISCOVERY':'SIMULATION'}</span><strong>Configuration management database</strong><p>Discovery is reconciled by stable IDs. Operator-owned metadata is preserved, missing resources become stale, and every change is audited.</p></div><small>{data.status.lastReconciledAt?`Reconciled ${relativeTime(data.status.lastReconciledAt)}`:'Awaiting reconciliation'}</small></div>
    {error&&<div className="inline-error"><CircleAlert size={15}/>{error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Configuration items" value={String(data.items.length)} detail="Discovered and manually maintained" icon={Database}/><Metric label="Relationships" value={String(data.relationships.length)} detail="Hosts, contains, runs on, and depends on" icon={Link2}/><Metric label="Stale items" value={String(data.status.stale)} detail={data.status.stale?'Review before retirement':'Discovery is current'} icon={Timer} tone={data.status.stale?'bad':'good'}/><Metric label="Audited changes" value={String(data.changes.length)} detail="Recent reconciliation and operator actions" icon={GitBranch}/></div>
    <div className="cmdb-grid"><section className="panel cmdb-items"><div className="panel-head"><div><h2>Configuration items</h2><p>Authoritative inventory with ownership and lifecycle</p></div><div className="cmdb-filters"><div className="search"><Search size={14}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search inventory"/></div><select value={classFilter} onChange={event=>setClassFilter(event.target.value)}><option value="all">All classes</option>{[...new Set(data.items.map(item=>item.class))].sort().map(value=><option key={value} value={value}>{value.replace('_',' ')}</option>)}</select></div></div><div className="ci-list">{filtered.map(item=><button className="ci-row" key={item.id} onClick={()=>edit(item)}><span className={`ci-icon ${item.source}`}><Database size={15}/></span><span className="ci-name"><strong>{item.name}</strong><small>{item.class.replace('_',' ')} · {item.externalId}</small></span><span className="ci-owner"><small>OWNER</small><strong>{item.owner||'Unassigned'}</strong></span><span className={`ci-criticality ${item.criticality}`}>{item.criticality}</span><span className={`ci-lifecycle ${item.lifecycle}`}>{item.lifecycle}</span></button>)}</div></section>
      <aside className="cmdb-side"><section className="panel"><div className="panel-head"><div><h2>Relationships</h2><p>Recent dependency map</p></div></div><div className="cmdb-relations">{data.relationships.slice(0,8).map(relation=><div key={relation.id}><strong>{itemName(relation.fromId)}</strong><span>{relation.type.replace('_',' ')}</span><strong>{itemName(relation.toId)}</strong></div>)}</div></section><section className="panel"><div className="panel-head"><div><h2>Change history</h2><p>Discovery and operator audit trail</p></div></div><div className="cmdb-changes">{data.changes.slice(0,8).map(change=><div key={change.id}><GitBranch size={13}/><span><strong>{itemName(change.ciId)}</strong><small>{change.action.replaceAll('_',' ')} · {relativeTime(change.changedAt)}</small></span></div>)}</div></section></aside>
    </div>
  </section>;
}

function AlertsDashboard({data,incidents,monitors,loading,error,acknowledge,suppress}:{data:AlertsResponse|null,incidents:Incident[],monitors:Monitor[],loading:boolean,error:string,acknowledge:(id:string)=>Promise<void>,suppress:(id:string)=>Promise<void>}) {
  const [busy,setBusy]=useState(''); const [actionError,setActionError]=useState('');
  if (loading && !data) return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Loading alert operations…</strong><span>Reading rules, incidents, and notification status.</span></div></section>;
  if (error && !data) return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Alerts unavailable</strong><span>{error}</span></div></section>;
  if (!data) return null;
  const active = incidents.filter(incident=>incident.status!=='resolved'); const resolved = incidents.filter(incident=>incident.status==='resolved');
  const critical = active.filter(incident=>incident.severity==='critical').length; const acknowledged = active.filter(incident=>incident.status==='acknowledged').length;
  const suppressed = data.rules.filter(rule=>rule.suppressedUntil && new Date(rule.suppressedUntil).getTime()>Date.now()).length;
  const monitorName = (id:string) => monitors.find(monitor=>monitor.id===id)?.name || id;
  async function act(id:string,action:()=>Promise<void>) { setBusy(id); setActionError(''); try { await action(); } catch(value) { setActionError(value instanceof Error?value.message:'Alert action failed'); } finally { setBusy(''); } }
  return <section className="content infrastructure-content alerts-content">
    <div className="inventory-banner alerts-banner"><div><span className={`source-badge ${data.notifications.mode==='live'?'proxmox':'simulation'}`}>{data.notifications.mode==='live'?'LIVE DELIVERY':'SIMULATION'}</span><strong>Incident response</strong><p>{data.notifications.mode==='live'?'Notifications are enabled for configured channels.':'Notifications are recorded but not sent. Enable real delivery after configuring a channel.'}</p></div><div className="notification-channels"><span className={data.notifications.webhookConfigured?'configured':''}>Webhook {data.notifications.webhookConfigured?'ready':'not set'}</span><span className={data.notifications.emailConfigured?'configured':''}>Email {data.notifications.emailConfigured?'ready':'not set'}</span></div></div>
    {(error||actionError)&&<div className="inline-error"><CircleAlert size={15}/>{actionError||error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Active incidents" value={String(active.length)} detail={active.length?'Response required':'No active incidents'} icon={Bell} tone={active.length?'bad':'good'}/><Metric label="Critical" value={String(critical)} detail="Release and service impact" icon={CircleAlert} tone={critical?'bad':'good'}/><Metric label="Acknowledged" value={String(acknowledged)} detail="Owned by an operator" icon={Check}/><Metric label="Suppressed rules" value={String(suppressed)} detail="Temporary maintenance windows" icon={Timer}/></div>
    <div className="alerts-grid">
      <section className="panel incidents-panel"><div className="panel-head"><div><h2>Active incidents</h2><p>Consecutive failures grouped into actionable events</p></div><span className="resource-count">{active.length} active</span></div><div className="incident-list">{active.length?active.map(incident=><article className={`incident-card ${incident.severity}`} key={incident.id}><div className="incident-main"><span className={`incident-severity ${incident.severity}`}>{incident.severity}</span><div><strong>{incident.title}</strong><p>{incident.summary}</p><small>{monitorName(incident.monitorId)} · Opened {relativeTime(incident.openedAt)} · {incident.occurrences} occurrence{incident.occurrences===1?'':'s'}</small></div></div><div className="incident-actions"><span className={`incident-status ${incident.status}`}>{incident.status}</span>{incident.status==='open'&&<button className="secondary" disabled={busy===incident.id} onClick={()=>act(incident.id,()=>acknowledge(incident.id))}>{busy===incident.id?'Saving…':'Acknowledge'}</button>}</div></article>):<div className="empty-incidents"><ShieldCheck/><strong>No active incidents</strong><span>Sentinel will open one when an alert rule reaches its failure threshold.</span></div>}</div></section>
      <section className="panel rules-panel"><div className="panel-head"><div><h2>Alert rules</h2><p>Thresholds, severity, and notification cooldowns</p></div><span className="resource-count">{data.rules.length} rules</span></div><div className="rule-list">{data.rules.map(rule=>{const isSuppressed=Boolean(rule.suppressedUntil&&new Date(rule.suppressedUntil).getTime()>Date.now());return <article className="rule-row" key={rule.id}><div className={`rule-icon ${rule.severity}`}><Bell size={15}/></div><div><strong>{rule.name}</strong><small>{rule.monitorId==='*'?'All service monitors':monitorName(rule.monitorId)}</small><p>Open after {rule.failureThreshold} consecutive failure{rule.failureThreshold===1?'':'s'} · notify every {formatDuration(rule.cooldownSeconds)}</p></div><span className={`rule-state ${isSuppressed?'suppressed':rule.severity}`}>{isSuppressed?`Suppressed ${relativeTime(rule.suppressedUntil!)}`:rule.severity}</span><button className="monitor-run" disabled={busy===rule.id||isSuppressed} onClick={()=>act(rule.id,()=>suppress(rule.id))}>{isSuppressed?'Paused':busy===rule.id?'Saving…':'Suppress 1h'}</button></article>})}</div></section>
    </div>
    {resolved.length>0&&<section className="panel resolved-panel"><div className="panel-head"><div><h2>Recently resolved</h2><p>Recovery history retained with the incident record</p></div><span className="resource-count">{resolved.length} resolved</span></div><div className="resolved-list">{resolved.slice(0,6).map(incident=><div key={incident.id}><Check size={14}/><span><strong>{incident.title}</strong><small>Resolved {relativeTime(incident.resolvedAt||incident.updatedAt)}</small></span><em>{incident.occurrences} checks</em></div>)}</div></section>}
  </section>;
}

function TopologyDashboard({data,loading,error,refresh,removeMapping}:{data:TopologySnapshot|null,loading:boolean,error:string,refresh:()=>void,removeMapping:(id:string)=>Promise<void>}) {
  const [actionError,setActionError]=useState(''); const [busy,setBusy]=useState('');
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Building dependency graph…</strong><span>Connecting Proxmox, Docker, applications, and service checks.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Topology unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if(!data)return null;
  const nodeMap=new Map(data.nodes.map(node=>[node.id,node])); const dependencyEdges=data.edges.filter(edge=>edge.relation==='monitors');
  async function remove(id:string){setBusy(id);setActionError('');try{await removeMapping(id)}catch(value){setActionError(value instanceof Error?value.message:'Unable to remove mapping')}finally{setBusy('')}}
  return <section className="content infrastructure-content topology-content">
    <div className="inventory-banner topology-banner"><div><span className="source-badge proxmox">CORRELATION ENGINE</span><strong>Explainable dependency analysis</strong><p>Sentinel follows discovered and confirmed relationships upstream, then ranks unhealthy dependencies without taking automated action.</p></div><small>Updated {new Date(data.collectedAt).toLocaleTimeString()}</small></div>
    {(error||actionError)&&<div className="inline-error"><CircleAlert size={15}/>{actionError||error}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Topology nodes" value={String(data.summary.nodes)} detail={`${data.summary.relationships} relationships`} icon={GitBranch}/><Metric label="Monitored services" value={String(data.summary.services)} detail={`${data.summary.unmappedServices} need mapping review`} icon={Activity}/><Metric label="Unhealthy dependencies" value={String(data.summary.unhealthyDependencies)} detail="Upstream resources to inspect" icon={CircleAlert} tone={data.summary.unhealthyDependencies?'bad':'good'}/><Metric label="Correlated groups" value={String(data.summary.correlatedGroups)} detail="Active incidents consolidated" icon={BrainCircuit} tone={data.summary.correlatedGroups?'bad':'good'}/></div>
    <section className="panel correlation-panel"><div className="panel-head"><div><h2>Probable root causes</h2><p>Evidence-based grouping; confidence is a heuristic, not an automated diagnosis</p></div><span className="resource-count">{data.correlations.length} groups</span></div>{data.correlations.length?<div className="correlation-list">{data.correlations.map(group=><article className={`correlation-card ${group.severity}`} key={group.id}><div className="confidence"><strong>{group.confidence}%</strong><span>CONFIDENCE</span></div><div className="correlation-body"><span className={`incident-severity ${group.severity}`}>{group.severity}</span><h3>{group.title}</h3><p>{group.explanation}</p><div className="affected">{group.affectedServices.map(service=><span key={service}>{service}</span>)}</div><ul>{group.evidence.map(item=><li key={item}>{item}</li>)}</ul></div></article>)}</div>:<div className="empty-incidents"><BrainCircuit/><strong>No active correlation groups</strong><span>When incidents open, Sentinel will compare them with unhealthy upstream dependencies.</span></div>}</section>
    <div className="topology-grid"><section className="panel relationship-panel"><div className="panel-head"><div><h2>Service dependencies</h2><p>Confirmed mappings override automatically inferred matches</p></div><span className="resource-count">{dependencyEdges.length} linked</span></div><div className="relationship-list">{dependencyEdges.length?dependencyEdges.map(edge=>{const from=nodeMap.get(edge.from),to=nodeMap.get(edge.to);return <div className="relationship-row" key={`${edge.from}-${edge.to}`}><NodeBadge node={from}/><span className="relationship-line"><i/> {edge.inferred?'inferred':'confirmed'} <i/></span><NodeBadge node={to}/>{!edge.inferred&&<span className="confirmed-badge">CONFIRMED</span>}</div>}):<div className="empty-resource">No service dependencies found. Add a mapping to correlate incidents with infrastructure.</div>}</div></section>
      <section className="panel mapping-panel"><div className="panel-head"><div><h2>Manual overrides</h2><p>Operator-confirmed service-to-resource links</p></div><span className="resource-count">{data.mappings.length} saved</span></div><div className="mapping-list">{data.mappings.length?data.mappings.map(mapping=><div key={mapping.id}><Link2 size={14}/><span><strong>{nodeMap.get(mapping.resourceId)?.name||mapping.resourceId}</strong><small>{nodeMap.get(`service/${mapping.monitorId}`)?.name||mapping.monitorId}</small></span><button aria-label="Remove mapping" disabled={busy===mapping.id} onClick={()=>remove(mapping.id)}>{busy===mapping.id?<RefreshCw className="spin" size={14}/>:<Trash2 size={14}/>}</button></div>):<div className="empty-resource">No overrides saved. Sentinel is using name and target matching.</div>}</div></section></div>
  </section>;
}

function NodeBadge({node}:{node?:TopologyNode}) { if(!node)return <span className="topology-node unknown"><CircleAlert size={14}/><span><strong>Unknown</strong><small>Missing resource</small></span></span>; const Icon=node.type==='node'||node.type==='vm'?Server:node.type==='lxc'||node.type==='container'?Box:node.type==='docker-host'||node.type==='application'?Boxes:Activity; return <span className={`topology-node ${node.health}`}><Icon size={15}/><span><strong>{node.name}</strong><small>{node.type} · {node.state}</small></span></span> }

function ProxmoxOperationsDashboard({data,loading,error,refresh}:{data:ProxmoxOperationsResponse|null,loading:boolean,error:string,refresh:()=>Promise<void>}){
  if(loading&&!data)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Collecting Proxmox operations…</strong><span>Checking quorum, storage, tasks, backups, HA, and replication.</span></div></section>;
  if(error&&!data)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Cluster operations unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  const current=data?.current;if(!data||!current)return null;const quorum=current.quorum.quorate===null?'Not reported':current.quorum.quorate?'Quorate':'Lost';const backupAge=current.backup.ageHours===null?'Unknown':`${current.backup.ageHours}h`;
  return <section className="content infrastructure-content operations-content">
    <div className="inventory-banner operations-banner"><div><span className={`source-badge ${current.mode==='live'?'proxmox':'simulation'}`}>{current.mode==='live'?'LIVE PROXMOX':'SIMULATION'}</span><strong>{current.clusterName} operational health</strong><p>Cluster-level safeguards detect quorum loss, offline nodes, storage pressure, failed tasks, stale backups, and HA state before workloads are affected.</p></div><small>Collected {relativeTime(current.collectedAt)} · every {Math.round(data.status.intervalSeconds/60)} min</small></div>
    {(error||current.collectionErrors.length>0)&&<div className="inline-error"><CircleAlert size={15}/>{error||`${current.collectionErrors.length} optional API checks unavailable: ${current.collectionErrors.join(' · ')}`}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Cluster quorum" value={quorum} detail={`${current.quorum.nodesOnline} of ${current.quorum.nodesTotal} nodes online`} icon={ShieldCheck} tone={current.quorum.quorate===false?'bad':'good'}/><Metric label="Backup freshness" value={backupAge} detail={`${current.backup.successful24h} successful · ${current.backup.failed24h} failed in 24h`} icon={HardDrive} tone={current.backup.health==='critical'||current.backup.health==='warning'?'bad':'good'}/><Metric label="Failed tasks" value={String(current.summary.failedTasks24h)} detail="During the last 24 hours" icon={CircleAlert} tone={current.summary.failedTasks24h?'bad':'good'}/><Metric label="Storage pressure" value={String(current.summary.storagePressure)} detail={`${current.storage.length} storage targets checked`} icon={Database} tone={current.summary.storagePressure?'bad':'good'}/></div>
    <div className="operations-grid"><section className="panel operations-findings"><div className="panel-head"><div><h2>Operational findings</h2><p>Actionable cluster conditions ordered by severity</p></div><span className={`health-pill ${current.health}`}>{current.health}</span></div><div className="operations-finding-list">{current.findings.length?current.findings.map(item=><article className={item.severity} key={item.id}><span>{item.severity==='critical'?<CircleAlert/>:<Timer/>}</span><div><strong>{item.title}</strong><p>{item.detail}</p><small>{item.category}{item.resourceId?` · ${item.resourceId}`:''}</small></div><em>{item.severity}</em></article>):<div className="empty-incidents"><ShieldCheck/><strong>No operational findings</strong><span>Quorum, storage, tasks, backups, and HA are within configured targets.</span></div>}</div></section><section className="panel operations-storage"><div className="panel-head"><div><h2>Storage capacity</h2><p>Warning at {data.status.storageWarningPercent}% · critical at {data.status.storageCriticalPercent}%</p></div></div><div className="operations-storage-list">{current.storage.map(item=><article key={item.id}><div><strong>{item.name}</strong><small>{item.node} · {item.state}</small></div><span><i style={{width:`${Math.min(item.usagePercent,100)}%`}} className={item.health}/></span><em>{item.usagePercent}%<small>{formatBytes(item.usedBytes)} / {formatBytes(item.totalBytes)}</small></em></article>)}</div></section></div>
    <div className="operations-grid"><section className="panel operations-tasks"><div className="panel-head"><div><h2>Recent tasks</h2><p>Newest cluster operations from the last 24 hours</p></div><span className="resource-count">{current.recentTasks.length} retained</span></div><div className="operations-task-list">{current.recentTasks.slice(0,10).map(item=><article key={item.id}><span className={/^(OK|running)$/i.test(item.status)?'healthy':'critical'}>{/^(OK|running)$/i.test(item.status)?<Check/>:<CircleAlert/>}</span><div><strong>{item.type}</strong><small>{item.node} · {item.user} · {relativeTime(item.startedAt)}</small></div><em>{item.status}</em></article>)}</div></section><section className="panel operations-ha"><div className="panel-head"><div><h2>HA and replication</h2><p>Managed resources and scheduled data protection</p></div></div><div className="operations-ha-summary"><div><strong>{current.ha.filter(item=>item.kind==='service').length}</strong><span>HA services</span></div><div><strong>{current.summary.haProblems}</strong><span>HA problems</span></div><div><strong>{current.summary.replicationJobs}</strong><span>Replication jobs</span></div></div><div className="operations-replication-list">{current.replication.filter(item=>item.enabled).map(item=><article key={item.id}><GitBranch/><div><strong>{item.id}</strong><small>{item.source} → {item.target} · {item.schedule}</small></div></article>)}{!current.replication.some(item=>item.enabled)&&<p className="snow-empty">No enabled replication jobs were reported.</p>}</div></section></div>
  </section>
}

function InventoryDashboard({inventory,loading,error,refresh}:{inventory:ProxmoxInventory|null,loading:boolean,error:string,refresh:()=>void}) {
  if (loading && !inventory) return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Discovering Proxmox resources…</strong><span>Reading nodes, workloads, and storage.</span></div></section>;
  if (error && !inventory) return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Inventory unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if (!inventory) return null;
  const groups = groupInventory(inventory);
  const workloads = inventory.summary.virtualMachines + inventory.summary.lxcContainers;

  return <section className="content infrastructure-content">
    <div className="inventory-banner"><div><span className={`source-badge ${inventory.source}`}>{inventory.source === 'simulation' ? 'SIMULATION' : 'LIVE PROXMOX'}</span><strong>{inventory.clusterName}</strong><p>{inventory.source === 'simulation' ? 'Safe sample data is active. Configure a read-only token when you are ready to connect the lab.' : 'Read-only inventory collected directly from the Proxmox API.'}</p></div><small>Updated {new Date(inventory.collectedAt).toLocaleTimeString()}</small></div>
    {error && <div className="inline-error"><CircleAlert size={15}/>{error}. Displaying the last successful inventory.</div>}
    <div className="metric-grid inventory-metrics">
      <Metric label="Cluster nodes" value={String(inventory.summary.nodes)} detail="Proxmox hosts discovered" icon={Server} tone="good"/>
      <Metric label="VMs and LXC" value={String(workloads)} detail={`${inventory.summary.runningWorkloads} running · ${inventory.summary.stoppedWorkloads} stopped`} icon={Boxes}/>
      <Metric label="Storage pools" value={String(inventory.summary.storagePools)} detail="Capacity checks enabled" icon={HardDrive}/>
      <Metric label="Health warnings" value={String(inventory.summary.warnings)} detail={inventory.summary.warnings ? 'Needs review' : 'No infrastructure warnings'} icon={CircleAlert} tone={inventory.summary.warnings ? 'bad' : 'good'}/>
    </div>
    <section className="panel inventory-panel"><div className="panel-head"><div><h2>Infrastructure hierarchy</h2><p>Proxmox node → VM or LXC → application monitoring in the next stage</p></div><span className="resource-count">{inventory.resources.length} resources</span></div>
      <div className="node-grid">{groups.map(group => <NodeCard key={group.node.id} node={group.node} workloads={group.workloads} storage={group.storage}/>)}</div>
    </section>
  </section>;
}

function NodeCard({node,workloads,storage}:{node:ProxmoxResource,workloads:ProxmoxResource[],storage:ProxmoxResource[]}) {
  const memory = percent(node.memoryUsedBytes,node.memoryTotalBytes); const running = workloads.filter(item => item.state === 'running').length;
  return <article className="node-card">
    <div className="node-head"><span className="node-icon"><Server size={18}/></span><div><strong>{node.name}</strong><small>{node.state} · {running}/{workloads.length} workloads running</small></div><HealthBadge health={node.health}/></div>
    <div className="node-usage"><Usage label="CPU" value={node.cpuPercent === undefined ? null : Math.round(node.cpuPercent)}/><Usage label="Memory" value={memory}/></div>
    <div className="resource-section"><span className="resource-title">WORKLOADS</span>{workloads.length ? workloads.map(item => <ResourceRow key={item.id} resource={item}/>) : <div className="empty-resource">No VMs or LXC containers discovered</div>}</div>
    <div className="resource-section"><span className="resource-title">STORAGE</span>{storage.length ? storage.map(item => <ResourceRow key={item.id} resource={item}/>) : <div className="empty-resource">No node storage reported</div>}</div>
  </article>;
}

function ResourceRow({resource}:{resource:ProxmoxResource}) {
  const Icon = resource.type === 'storage' ? HardDrive : resource.type === 'lxc' ? Box : Server;
  const utilization = resource.type === 'storage' ? percent(resource.diskUsedBytes,resource.diskTotalBytes) : percent(resource.memoryUsedBytes,resource.memoryTotalBytes);
  const detail = resource.type === 'storage' ? `${formatBytes(resource.diskUsedBytes)} / ${formatBytes(resource.diskTotalBytes)}` : `${resource.type.toUpperCase()}${resource.vmid ? ` ${resource.vmid}` : ''} · ${resource.state}`;
  return <div className="resource-row"><span><Icon size={15}/></span><div><strong>{resource.name}</strong><small>{detail}</small></div>{utilization !== null && <em>{utilization}%</em>}<HealthBadge health={resource.health}/></div>;
}

function Usage({label,value}:{label:string,value:number|null}) { return <div><span>{label}<em>{value === null ? '—' : `${value}%`}</em></span><div className="usage-track"><i style={{width:`${value || 0}%`}}/></div></div> }
function HealthBadge({health}:{health:ProxmoxResource['health']}) { return <span className={`health-badge ${health}`}><i/>{health}</span> }

function DockerDashboard({inventory,loading,error,refresh}:{inventory:DockerInventory|null,loading:boolean,error:string,refresh:()=>void}) {
  if (loading && !inventory) return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Discovering Docker applications…</strong><span>Reading containers, health checks, ports, and Compose labels.</span></div></section>;
  if (error && !inventory) return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Docker inventory unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if (!inventory) return null;
  const grouped = inventory.containers.reduce<Record<string,DockerContainer[]>>((projects,container) => { const key = container.composeProject || 'Standalone containers'; (projects[key] ||= []).push(container); return projects; }, {});
  return <section className="content infrastructure-content">
    <div className="inventory-banner docker-banner"><div><span className={`source-badge ${inventory.source}`}>{inventory.source === 'simulation' ? 'SIMULATION' : 'LIVE DOCKER'}</span><strong>{inventory.engineName}</strong><p>{inventory.source === 'simulation' ? 'Sample application data is active. Configure a Docker socket to discover the real container host.' : `Docker Engine ${inventory.engineVersion || ''} · read-only discovery`}</p></div><small>Updated {new Date(inventory.collectedAt).toLocaleTimeString()}</small></div>
    {error && <div className="inline-error"><CircleAlert size={15}/>{error}. Displaying the last successful container inventory.</div>}
    <div className="metric-grid inventory-metrics">
      <Metric label="Containers" value={String(inventory.summary.total)} detail={`${inventory.summary.running} running · ${inventory.summary.stopped} stopped`} icon={Box}/>
      <Metric label="Healthy" value={String(inventory.summary.healthy)} detail="Docker health checks passing" icon={ShieldCheck} tone="good"/>
      <Metric label="Unhealthy" value={String(inventory.summary.unhealthy)} detail={inventory.summary.unhealthy ? 'Immediate review required' : 'No failed health checks'} icon={CircleAlert} tone={inventory.summary.unhealthy ? 'bad' : 'good'}/>
      <Metric label="Compose projects" value={String(inventory.summary.composeProjects)} detail="Application groups discovered" icon={Boxes}/>
    </div>
    <section className="panel inventory-panel"><div className="panel-head"><div><h2>Application inventory</h2><p>Compose project → service → container health and exposed ports</p></div><span className="resource-count">{Object.keys(grouped).length} groups</span></div>
      <div className="app-grid">{Object.entries(grouped).map(([project,containers]) => <article className="app-card" key={project}><div className="app-head"><span><Boxes size={17}/></span><div><strong>{project}</strong><small>{containers.length} service{containers.length === 1 ? '' : 's'}</small></div><HealthBadge health={containers.some(item => item.health === 'critical') ? 'critical' : containers.some(item => item.health === 'warning') ? 'warning' : 'healthy'}/></div>{containers.map(container => <ContainerRow key={container.id} container={container}/>)}</article>)}</div>
    </section>
  </section>;
}

function ContainerRow({container}:{container:DockerContainer}) {
  const ports = container.ports.filter(port => port.publicPort).map(port => `${port.publicPort}:${port.privatePort}/${port.protocol}`).join(', ');
  return <div className="container-row"><span><Box size={15}/></span><div><strong>{container.composeService || container.name}</strong><small>{container.image}</small><em>{ports || 'No published ports'} · {container.status}</em></div><HealthBadge health={container.health}/></div>;
}

function HardwareDashboard({inventory,operations,loading,error,refresh,maintain,baseline}:{inventory:HardwareInventory|null,operations:HardwareOperations|null,loading:boolean,error:string,refresh:()=>void,maintain:(deviceId:string)=>Promise<void>,baseline:(deviceId:string)=>Promise<void>}){
  const [busy,setBusy]=useState('');const [actionError,setActionError]=useState('');
  async function act(key:string,action:()=>Promise<void>){setBusy(key);setActionError('');try{await action()}catch(value){setActionError(value instanceof Error?value.message:'Hardware operation failed')}finally{setBusy('')}}
  if(loading&&!inventory)return <section className="content"><div className="inventory-state"><RefreshCw className="spin"/><strong>Discovering physical infrastructure…</strong><span>Reading Redfish and SNMP health data.</span></div></section>;
  if(error&&!inventory)return <section className="content"><div className="inventory-state error-state"><CircleAlert/><strong>Hardware inventory unavailable</strong><span>{error}</span><button className="secondary" onClick={refresh}>Try again</button></div></section>;
  if(!inventory)return null;
  const active=operations?.findings.filter(item=>item.status==='active')||[];
  return <section className="content hardware-content"><div className="inventory-banner"><div><span className={`source-badge ${inventory.mode==='live'?'proxmox':'simulation'}`}>{inventory.mode==='live'?'LIVE HARDWARE':'SIMULATION'}</span><strong>Physical infrastructure health</strong><p>Threshold findings, maintenance suppression, and firmware drift are evaluated from read-only Redfish and SNMPv3 data.</p></div><small>Updated {new Date(inventory.collectedAt).toLocaleTimeString()}</small></div>{(error||actionError)&&<div className="inline-error"><CircleAlert size={15}/>{actionError||`${error}. Showing the last successful collection.`}</div>}
    <div className="metric-grid inventory-metrics"><Metric label="Devices" value={String(inventory.summary.devices)} detail={`${inventory.summary.components} components`} icon={HardDrive}/><Metric label="Active findings" value={String(operations?.summary.active||0)} detail={`${operations?.summary.critical||0} critical · ${operations?.summary.warnings||0} warning`} icon={CircleAlert} tone={operations?.summary.critical||operations?.summary.warnings?'bad':'good'}/><Metric label="Suppressed" value={String(operations?.summary.suppressed||0)} detail={`${operations?.summary.maintenance||0} active maintenance windows`} icon={Timer}/><Metric label="Firmware baselines" value={String(operations?.summary.baselines||0)} detail="Approved versions tracked for drift" icon={ShieldCheck}/></div>
    <section className="panel hardware-findings"><div className="panel-head"><div><h2>Operational findings</h2><p>Suppressed findings remain visible but do not count as actionable</p></div><span className="resource-count">{active.length} active</span></div><div className="finding-list">{active.length?active.map(finding=><article className={`${finding.severity} ${finding.suppressed?'suppressed':''}`} key={finding.id}><span><CircleAlert size={15}/></span><div><strong>{finding.title}</strong><p>{finding.detail}</p><small>{finding.deviceName} · {finding.kind.replaceAll('_',' ')} · first seen {relativeTime(finding.firstSeenAt)}</small></div><em>{finding.suppressed?'maintenance':finding.severity}</em></article>):<div className="empty-resource">No active hardware findings.</div>}</div></section>
    <section className="panel"><div className="panel-head"><div><h2>Hardware inventory</h2><p>Use a two-hour window for planned work or accept a reported firmware version as the baseline</p></div><span className="resource-count">{inventory.devices.length} devices</span></div><div className="hardware-grid">{inventory.devices.map(device=>{const maintenance=operations?.maintenanceWindows.some(item=>item.deviceId===device.id&&new Date(item.startsAt)<=new Date()&&new Date(item.endsAt)>new Date());const hasBaseline=operations?.firmwareBaselines.some(item=>item.deviceId===device.id);return <article className={`hardware-card ${device.health}`} key={device.id}><div className="hardware-head"><span>{device.category==='physical_server'?<Server/>:device.category==='ups'||device.category==='pdu'?<Activity/>:<Network/>}</span><div><strong>{device.name}</strong><small>{device.manufacturer||'Unknown vendor'} {device.model||''}</small></div><em>{maintenance?'maintenance':device.health}</em></div><dl><div><dt>Management</dt><dd>{device.managementAddress}</dd></div><div><dt>Source</dt><dd>{device.source.toUpperCase()}</dd></div><div><dt>Status</dt><dd>{device.status}</dd></div><div><dt>Firmware</dt><dd>{device.firmwareVersion||'—'}</dd></div></dl><div className="component-list">{device.components.slice(0,4).map(component=><span className={component.health} key={component.id}><i/>{component.name}<em>{component.value!==undefined?`${component.value}${component.unit||''}`:component.detail||component.health}</em></span>)}</div><div className="hardware-actions"><button disabled={busy===`maintain-${device.id}`||maintenance} onClick={()=>act(`maintain-${device.id}`,()=>maintain(device.id))}>{maintenance?'In maintenance':busy===`maintain-${device.id}`?'Saving…':'Maintenance 2h'}</button>{device.firmwareVersion&&<button disabled={busy===`baseline-${device.id}`} onClick={()=>act(`baseline-${device.id}`,()=>baseline(device.id))}>{busy===`baseline-${device.id}`?'Saving…':hasBaseline?'Update baseline':'Set baseline'}</button>}</div></article>})}</div></section>
  </section>;
}

function ConnectionsDashboard({status}:{status:ConnectionStatus|null}) {
  return <section className="content connections-content">
    <div className="notice"><span className="notice-icon"><ShieldCheck size={19}/></span><div><strong>Credentials stay outside Sentinel</strong><p>Connections use environment variables and read-only permissions. Tokens and socket credentials are never returned to the browser.</p></div></div>
    <div className="connection-grid">
      <ConnectionCard icon={Server} name="Proxmox VE" configured={status?.proxmox.configured} description="Discovers cluster nodes, QEMU VMs, LXC containers, storage, state, and utilization." variables={["PVE_URL=https://proxmox.example:8006","PVE_TOKEN_ID=sentinel@pve!monitoring","PVE_TOKEN_SECRET=replace-with-token-secret"]}/>
      <ConnectionCard icon={Box} name="Docker Engine" configured={status?.docker.configured} description="Discovers containers, Compose projects, health checks, images, state, and published ports." variables={["DOCKER_SOCKET_PATH=/var/run/docker.sock"]}/>
      <ConnectionCard icon={Server} name="Redfish" configured={status?.redfish.configured} description={`Collects server chassis, power, thermal, fan, storage, and firmware health from ${status?.redfish.targets||0} configured target(s).`} variables={['SENTINEL_REAL_HARDWARE=true','SENTINEL_REDFISH_TARGETS=[{"id":"pve-01","name":"pve-01","url":"https://idrac-pve-01","username":"sentinel","password":"secret"}]']}/>
      <ConnectionCard icon={Network} name="SNMP exporter" configured={status?.snmp.configured} description={`Collects interfaces, errors, UPS battery, and load through an SNMPv3 exporter for ${status?.snmp.targets||0} target(s).`} variables={['SNMP_EXPORTER_URL=http://127.0.0.1:9116','SNMP_EXPORTER_ALLOW_HTTP=true','SENTINEL_SNMP_TARGETS=[{"id":"core","name":"Core switch","target":"10.20.0.2","category":"switch","module":"if_mib","auth":"sentinel_v3"}]']}/>
      <ConnectionCard icon={Globe2} name="Remote collectors" configured={status?.collectors.configured} description={`${status?.collectors.online||0} of ${status?.collectors.targets||0} registered collectors currently online.`} variables={['SENTINEL_URL=https://sentinel.example.net','SENTINEL_COLLECTOR_TOKEN=<one-time enrollment token>']}/>
    </div>
    <section className="panel safety-panel"><div className="panel-head"><div><h2>Connection safety</h2><p>Recommended permissions before enabling live discovery</p></div></div><div className="safety-list"><div><Check size={15}/><span><strong>Proxmox</strong>Use a dedicated API token with the PVEAuditor role at `/`.</span></div><div><Check size={15}/><span><strong>TLS</strong>Trust the Proxmox certificate or private CA on the Sentinel host.</span></div><div><Check size={15}/><span><strong>Docker</strong>Mount the socket read-only and never expose the Docker API publicly.</span></div><div><Check size={15}/><span><strong>Secrets</strong>Supply values through the service environment or a secrets manager.</span></div></div></section>
  </section>;
}

function ConnectionCard({icon:Icon,name,configured,description,variables}:{icon:typeof Server,name:string,configured?:boolean,description:string,variables:string[]}) {
  return <article className="connection-card"><div className="connection-head"><span><Icon size={20}/></span><div><h2>{name}</h2><p>{description}</p></div><span className={`connection-status ${configured ? 'configured' : 'setup'}`}><i/>{configured ? 'Configured' : 'Setup required'}</span></div><div className="env-block"><span>ENVIRONMENT VARIABLES</span>{variables.map(variable => <code key={variable}>{variable}</code>)}</div><small>{configured ? 'Configuration detected by the Sentinel API.' : 'Add these values to the Sentinel API environment, then restart the service.'}</small></article>;
}
function AddMonitorModal({close,save}:{close:()=>void,save:(input:{name:string;protocol:MonitorProtocol;target:string;intervalSeconds:number;timeoutMs:number;expectedStatus?:number})=>Promise<void>}) {
  const [name,setName]=useState(''); const [protocol,setProtocol]=useState<MonitorProtocol>('http'); const [target,setTarget]=useState(''); const [interval,setIntervalValue]=useState(60); const [error,setError]=useState(''); const [saving,setSaving]=useState(false);
  const placeholder = protocol === 'http' ? 'https://app.example.com/health' : protocol === 'tcp' ? 'database.local:5432' : 'app.example.com';
  return <div className="modal-wrap" onMouseDown={event=>event.target===event.currentTarget&&close()}><form className="modal" onSubmit={async event=>{event.preventDefault();setSaving(true);setError('');try{await save({name,protocol,target,intervalSeconds:interval,timeoutMs:5000,expectedStatus:protocol==='http'?200:undefined})}catch(value){setError(value instanceof Error?value.message:'Unable to add monitor')}finally{setSaving(false)}}}><button type="button" className="modal-x" onClick={close}><X/></button><span className="eyebrow">SERVICE MONITOR</span><h2>Add a health check</h2><p>Sentinel will run this check automatically and retain its recent results.</p>{error&&<div className="form-error">{error}</div>}<label>Monitor name<input required value={name} onChange={event=>setName(event.target.value)} placeholder="e.g. Plex web interface"/></label><label>Protocol<select value={protocol} onChange={event=>setProtocol(event.target.value as MonitorProtocol)}><option value="http">HTTP / HTTPS</option><option value="tcp">TCP port</option><option value="dns">DNS lookup</option></select></label><label>Target<input required value={target} onChange={event=>setTarget(event.target.value)} placeholder={placeholder}/></label><label>Check interval<select value={interval} onChange={event=>setIntervalValue(Number(event.target.value))}><option value={30}>Every 30 seconds</option><option value={60}>Every minute</option><option value={300}>Every 5 minutes</option><option value={900}>Every 15 minutes</option></select></label><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={saving}>{saving?'Adding…':'Add monitor'}</button></div></form></div>;
}
function AddAlertModal({close,save,monitors}:{close:()=>void,save:(input:{name:string;monitorId:string;failureThreshold:number;cooldownSeconds:number;severity:AlertSeverity})=>Promise<void>,monitors:Monitor[]}) {
  const [name,setName]=useState(''); const [monitorId,setMonitorId]=useState('*'); const [threshold,setThreshold]=useState(2); const [cooldown,setCooldown]=useState(900); const [severity,setSeverity]=useState<AlertSeverity>('critical'); const [error,setError]=useState(''); const [saving,setSaving]=useState(false);
  return <div className="modal-wrap" onMouseDown={event=>event.target===event.currentTarget&&close()}><form className="modal" onSubmit={async event=>{event.preventDefault();setSaving(true);setError('');try{await save({name,monitorId,failureThreshold:threshold,cooldownSeconds:cooldown,severity})}catch(value){setError(value instanceof Error?value.message:'Unable to add alert rule')}finally{setSaving(false)}}}><button type="button" className="modal-x" onClick={close}><X/></button><span className="eyebrow">ALERT POLICY</span><h2>Add an alert rule</h2><p>Open one incident after repeated failures, then notify again only after the cooldown.</p>{error&&<div className="form-error">{error}</div>}<label>Rule name<input required value={name} onChange={event=>setName(event.target.value)} placeholder="e.g. Critical service unavailable"/></label><label>Monitor<select value={monitorId} onChange={event=>setMonitorId(event.target.value)}><option value="*">All service monitors</option>{monitors.map(monitor=><option key={monitor.id} value={monitor.id}>{monitor.name}</option>)}</select></label><label>Failure threshold<select value={threshold} onChange={event=>setThreshold(Number(event.target.value))}><option value={1}>1 consecutive failure</option><option value={2}>2 consecutive failures</option><option value={3}>3 consecutive failures</option><option value={5}>5 consecutive failures</option></select></label><label>Severity<select value={severity} onChange={event=>setSeverity(event.target.value as AlertSeverity)}><option value="critical">Critical</option><option value="warning">Warning</option></select></label><label>Notification cooldown<select value={cooldown} onChange={event=>setCooldown(Number(event.target.value))}><option value={300}>5 minutes</option><option value={900}>15 minutes</option><option value={3600}>1 hour</option></select></label><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={saving}>{saving?'Adding…':'Add rule'}</button></div></form></div>;
}
function AddMappingModal({close,save,monitors,nodes}:{close:()=>void,save:(input:{monitorId:string;resourceId:string})=>Promise<void>,monitors:Monitor[],nodes:TopologyNode[]}) {
  const resources=nodes.filter(node=>node.type!=='service'); const [monitorId,setMonitorId]=useState(monitors[0]?.id||''); const [resourceId,setResourceId]=useState(resources[0]?.id||''); const [error,setError]=useState(''); const [saving,setSaving]=useState(false);
  return <div className="modal-wrap" onMouseDown={event=>event.target===event.currentTarget&&close()}><form className="modal" onSubmit={async event=>{event.preventDefault();setSaving(true);setError('');try{await save({monitorId,resourceId})}catch(value){setError(value instanceof Error?value.message:'Unable to map service')}finally{setSaving(false)}}}><button type="button" className="modal-x" onClick={close}><X/></button><span className="eyebrow">DEPENDENCY MAP</span><h2>Confirm a service dependency</h2><p>This override tells Sentinel which resource sits directly upstream of a monitored service.</p>{error&&<div className="form-error">{error}</div>}<label>Service monitor<select required value={monitorId} onChange={event=>setMonitorId(event.target.value)}>{monitors.map(monitor=><option value={monitor.id} key={monitor.id}>{monitor.name}</option>)}</select></label><label>Upstream resource<select required value={resourceId} onChange={event=>setResourceId(event.target.value)}>{resources.map(node=><option value={node.id} key={node.id}>{node.name} ({node.type})</option>)}</select></label><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={saving||!monitorId||!resourceId}>{saving?'Saving…':'Save mapping'}</button></div></form></div>;
}
function RetentionModal({close,save,current}:{close:()=>void,save:(input:{days:number;maxResults:number})=>Promise<void>,current:MetricsSnapshot['retention']}) {
  const [days,setDays]=useState(current.days);const [maxResults,setMaxResults]=useState(current.maxResults);const [error,setError]=useState('');const [saving,setSaving]=useState(false);
  return <div className="modal-wrap" onMouseDown={event=>event.target===event.currentTarget&&close()}><form className="modal" onSubmit={async event=>{event.preventDefault();setSaving(true);setError('');try{await save({days,maxResults})}catch(value){setError(value instanceof Error?value.message:'Unable to save retention policy')}finally{setSaving(false)}}}><button type="button" className="modal-x" onClick={close}><X/></button><span className="eyebrow">METRIC STORAGE</span><h2>Configure retention</h2><p>Sentinel removes results that exceed either limit. Lowering a limit permanently prunes matching history.</p>{error&&<div className="form-error">{error}</div>}<label>Retention period<select value={days} onChange={event=>setDays(Number(event.target.value))}><option value={7}>7 days</option><option value={30}>30 days</option><option value={90}>90 days</option><option value={180}>180 days</option><option value={365}>365 days</option></select></label><label>Maximum records<select value={maxResults} onChange={event=>setMaxResults(Number(event.target.value))}><option value={5000}>5,000 results</option><option value={25000}>25,000 results</option><option value={100000}>100,000 results</option></select></label><div className="retention-warning"><CircleAlert size={15}/>Reducing retention cannot restore records that are pruned.</div><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={saving}>{saving?'Saving…':'Save policy'}</button></div></form></div>;
}
function CiModal({item,close,save}:{item:ConfigurationItem|null,close:()=>void,save:(input:Record<string,unknown>,id?:string)=>Promise<void>}) {
  const [name,setName]=useState(item?.name||'');const [itemClass,setItemClass]=useState<CiClass>(item?.class||'application');const [owner,setOwner]=useState(item?.owner||'');const [environment,setEnvironment]=useState(item?.environment||'homelab');const [criticality,setCriticality]=useState<CiCriticality>(item?.criticality||'medium');const [lifecycle,setLifecycle]=useState(item?.lifecycle||'active');const [tags,setTags]=useState(item?.tags.join(', ')||'');const [error,setError]=useState('');const [saving,setSaving]=useState(false);
  const classes:CiClass[]=['node','vm','lxc','storage','docker_host','application','container','service','database','network','other'];
  return <div className="modal-wrap" onMouseDown={event=>event.target===event.currentTarget&&close()}><form className="modal" onSubmit={async event=>{event.preventDefault();setSaving(true);setError('');try{await save({name,...(!item?{class:itemClass}:{}),owner,environment,criticality,lifecycle,tags:tags.split(',').map(value=>value.trim()).filter(Boolean)},item?.id)}catch(value){setError(value instanceof Error?value.message:'Unable to save configuration item')}finally{setSaving(false)}}}><button type="button" className="modal-x" onClick={close}><X/></button><span className="eyebrow">CONFIGURATION ITEM</span><h2>{item?'Edit CI metadata':'Add a manual CI'}</h2><p>{item?'Discovery-owned fields remain reconciled while your ownership, lifecycle, and classification are preserved.':'Create records for services, databases, networks, or other assets that cannot be discovered automatically.'}</p>{error&&<div className="form-error">{error}</div>}<label>Name<input required value={name} onChange={event=>setName(event.target.value)} placeholder="e.g. Home automation database"/></label>{!item&&<label>Class<select value={itemClass} onChange={event=>setItemClass(event.target.value as CiClass)}>{classes.map(value=><option value={value} key={value}>{value.replace('_',' ')}</option>)}</select></label>}<label>Owner<input value={owner} onChange={event=>setOwner(event.target.value)} placeholder="Team or person responsible"/></label><label>Environment<input value={environment} onChange={event=>setEnvironment(event.target.value)} placeholder="homelab, production, staging"/></label><label>Criticality<select value={criticality} onChange={event=>setCriticality(event.target.value as CiCriticality)}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="critical">Critical</option></select></label>{item&&<label>Lifecycle<select value={lifecycle} onChange={event=>setLifecycle(event.target.value as ConfigurationItem['lifecycle'])}><option value="active">Active</option><option value="stale">Stale</option><option value="retired">Retired</option></select></label>}<label>Tags<input value={tags} onChange={event=>setTags(event.target.value)} placeholder="database, customer-facing, backup"/></label><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={saving}>{saving?'Saving…':'Save CI'}</button></div></form></div>;
}
function AddModal({close,save}:{close:()=>void,save:(t:Omit<Test,'id'>)=>void}) { const [name,setName]=useState(''); const [target,setTarget]=useState(''); const [kind,setKind]=useState<Kind>('frontend'); return <div className="modal-wrap" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="modal" onSubmit={e=>{e.preventDefault();save({name,target,kind,critical:true,timeoutMs:10000})}}><button type="button" className="modal-x" onClick={close}><X/></button><span className="eyebrow">NEW CHECK</span><h2>Add a durability test</h2><p>Define a target and include it in the next release-readiness run.</p><label>Test name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. LiveNX dashboard login"/></label><label>Surface<select value={kind} onChange={e=>setKind(e.target.value as Kind)}>{Object.entries(kindMeta).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}</select></label><label>Target URL<input required type="url" value={target} onChange={e=>setTarget(e.target.value)} placeholder="https://staging.example.com/health"/></label><div className="modal-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary">Add to suite</button></div></form></div> }

function median(values: number[]) { const sorted = [...values].sort((a, b) => a - b); const middle = Math.floor(sorted.length / 2); return Math.round(sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2); }
function relativeTime(value:string) { const seconds=Math.round((new Date(value).getTime()-Date.now())/1000); const formatter=new Intl.RelativeTimeFormat(undefined,{numeric:'auto'}); if(Math.abs(seconds)<60)return formatter.format(seconds,'second'); const minutes=Math.round(seconds/60); if(Math.abs(minutes)<60)return formatter.format(minutes,'minute'); const hours=Math.round(minutes/60); if(Math.abs(hours)<24)return formatter.format(hours,'hour'); return formatter.format(Math.round(hours/24),'day'); }
function formatDuration(seconds:number) { if(seconds<60)return `${seconds}s`; if(seconds<3600)return `${Math.round(seconds/60)}m`; return `${Math.round(seconds/3600)}h`; }
function formatBucket(seconds:number) { if(seconds<3600)return `${Math.round(seconds/60)} minute`;if(seconds<86_400)return `${Math.round(seconds/3600)} hour`;return `${Math.round(seconds/86_400)} day`; }
async function apiError(response: Response) { try { const body = await response.json(); return body.error || `Request failed (${response.status})`; } catch { return `Request failed (${response.status})`; } }
